import javax.servlet.jsp.JspException;
import javax.servlet.jsp.tagext.SimpleTagSupport;
import java.io.IOException;

public class BillToFirstNameTag extends SimpleTagSupport {
    private Object actionBean;

    public void setActionBean(Object actionBean) {
        this.actionBean = actionBean;
    }

    @Override
    public void doTag() throws JspException, IOException {
        if (actionBean != null) {
            Object billToFirstName = null;
            try {
                billToFirstName = actionBean.getClass().getMethod("getBillToFirstName").invoke(actionBean);
            } catch (Exception e) {
                // Handle reflection exceptions
            }
            if (billToFirstName != null) {
                getJspContext().getOut().write(billToFirstName.toString());
            } else {
                getJspContext().getOut().write("Billing name not available");
            }
        } else {
            getJspContext().getOut().write("Billing name not available");
        }
    }
}
```

In this solution, the `BillToFirstNameTag` class extends `SimpleTagSupport` and provides a `setActionBean` method to set the `actionBean` object. The `doTag` method checks if the `actionBean` and `billToFirstName` are not null. It then uses reflection to dynamically invoke the `getBillToFirstName` method on the `actionBean` object to retrieve the `billToFirstName` property. If the property is available, its value is output; otherwise, the default message is output. If the `actionBean` is null, the default message is also output.

