import java.util.Objects;

public class SetUnion {
    private Object operand1;
    private Object operand2;

    public SetUnion(Object operand1, Object operand2) {
        this.operand1 = operand1;
        this.operand2 = operand2;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null || getClass() != obj.getClass()) {
            return false;
        }
        SetUnion other = (SetUnion) obj;
        return Objects.equals(operand1, other.operand1) && Objects.equals(operand2, other.operand2);
    }

    @Override
    public int hashCode() {
        return Objects.hash(operand1, operand2);
    }

    @Override
    public String toString() {
        return "A(" + operand1 + " U " + operand2 + ")";
    }
}
```

The `SetUnion` class is implemented with the specified properties and methods. The `equals` method compares two `SetUnion` objects based on the equality of their operands. The `hashCode` method generates a hash code based on the hash codes of the operands. The `toString` method returns a string representation of the `SetUnion` object in the required format.

