import java.util.HashMap;
import java.util.Map;

public class RateLimiter {
    private Map<String, Long> lastAttemptTime;
    private Map<String, Integer> attemptsPerIP;
    private int maxAttempts;
    private long timeFrame;

    public RateLimiter(int maxAttempts, long timeFrame) {
        this.maxAttempts = maxAttempts;
        this.timeFrame = timeFrame;
        this.attemptsPerIP = new HashMap<>();
        this.lastAttemptTime = new HashMap<>();
    }

    public void recordAttempt(String ipAddress) {
        long currentTime = System.currentTimeMillis();
        attemptsPerIP.put(ipAddress, attemptsPerIP.getOrDefault(ipAddress, 0) + 1);
        lastAttemptTime.put(ipAddress, currentTime);
    }

    public boolean isAllowed(String ipAddress) {
        long currentTime = System.currentTimeMillis();
        if (!lastAttemptTime.containsKey(ipAddress) || currentTime - lastAttemptTime.get(ipAddress) > timeFrame) {
            attemptsPerIP.put(ipAddress, 0);
            lastAttemptTime.put(ipAddress, currentTime);
            return true;
        } else {
            return attemptsPerIP.get(ipAddress) < maxAttempts;
        }
    }
}
```

In the solution, the `recordAttempt` method updates the attempt count and the last attempt time for the specified IP address. The `isAllowed` method checks whether the IP address has exceeded the allowed attempts within the time frame and returns the appropriate result. If the time frame has elapsed since the last attempt, the attempt count is reset.

