interface Cipher {
    String encrypt(String plaintext, Object key);
    String decrypt(String ciphertext, Object key);
}

class CaesarCipher implements Cipher {
    @Override
    public String encrypt(String plaintext, Object key) {
        int shift = (int) key;
        StringBuilder result = new StringBuilder();
        for (char c : plaintext.toCharArray()) {
            if (Character.isLetter(c)) {
                char base = Character.isUpperCase(c) ? 'A' : 'a';
                result.append((char) ((c - base + shift) % 26 + base));
            } else {
                result.append(c);
            }
        }
        return result.toString();
    }

    @Override
    public String decrypt(String ciphertext, Object key) {
        int shift = (int) key;
        return encrypt(ciphertext, 26 - shift); // Decryption is essentially encryption with the inverse shift
    }
}

