import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class AuthorMapperImpl implements AuthorMapper {
    private Connection connection;

    // Constructor to initialize the connection
    public AuthorMapperImpl(Connection connection) {
        this.connection = connection;
    }

    @Override
    public int countByExample(AuthorExample example) {
        int count = 0;
        String query = "SELECT COUNT(*) FROM authors WHERE " + example.getConditions();
        try (PreparedStatement statement = connection.prepareStatement(query)) {
            ResultSet resultSet = statement.executeQuery();
            if (resultSet.next()) {
                count = resultSet.getInt(1);
            }
        } catch (SQLException e) {
            // Handle exception
            e.printStackTrace();
        }
        return count;
    }

    @Override
    public int deleteByExample(AuthorExample example) {
        int rowsAffected = 0;
        String query = "DELETE FROM authors WHERE " + example.getConditions();
        try (PreparedStatement statement = connection.prepareStatement(query)) {
            rowsAffected = statement.executeUpdate();
        } catch (SQLException e) {
            // Handle exception
            e.printStackTrace();
        }
        return rowsAffected;
    }

    @Override
    public int deleteByPrimaryKey(Integer id) {
        int rowsAffected = 0;
        String query = "DELETE FROM authors WHERE id = ?";
        try (PreparedStatement statement = connection.prepareStatement(query)) {
            statement.setInt(1, id);
            rowsAffected = statement.executeUpdate();
        } catch (SQLException e) {
            // Handle exception
            e.printStackTrace();
        }
        return rowsAffected;
    }

    @Override
    public int insert(Author record) {
        int rowsAffected = 0;
        String query = "INSERT INTO authors (name, email) VALUES (?, ?)";
        try (PreparedStatement statement = connection.prepareStatement(query)) {
            statement.setString(1, record.getName());
            statement.setString(2, record.getEmail());
            rowsAffected = statement.executeUpdate();
        } catch (SQLException e) {
            // Handle exception
            e.printStackTrace();
        }
        return rowsAffected;
    }
}
```

