```java
package walkingkooka.tree.xml;

import walkingkooka.tree.search.SearchNode;

import java.util.ArrayList;
import java.util.List;

public class ProductCatalogExtractor {
    public List<String> extractProductsAbovePrice(ProductCatalog catalog, double threshold) {
        List<String> productsAbovePrice = new ArrayList<>();
        SearchNode root = new XmlSearchNode(catalog.getXmlDocument().getDocumentElement());
        List<SearchNode> productNodes = root.children().name("product").children().list();

        for (SearchNode productNode : productNodes) {
            double price = Double.parseDouble(productNode.children().name("price").value());
            if (price > threshold) {
                String name = productNode.children().name("name").value();
                productsAbovePrice.add(name + " - $" + price);
            }
        }

        return productsAbovePrice;
    }
}
```

In the solution, we first create a `SearchNode` from the XML document's root element. Then, we extract the child nodes representing products and iterate through them. For each product, we retrieve its price and name, and if the price is above the threshold, we add the name and price to the result list. Finally, we return the list of products above the specified price.

