public class Queue {
    private Node front;
    private Node rear;

    private class Node {
        Object data;
        Node next;

        Node(Object data) {
            this.data = data;
            this.next = null;
        }
    }

    public void enqueue(Object element) {
        Node newNode = new Node(element);
        if (rear == null) {
            front = newNode;
            rear = newNode;
        } else {
            rear.next = newNode;
            rear = newNode;
        }
    }

    public Object dequeue() {
        if (front == null) {
            return null;
        }
        Object data = front.data;
        front = front.next;
        if (front == null) {
            rear = null;
        }
        return data;
    }

    public Object peek() {
        if (front == null) {
            return null;
        }
        return front.data;
    }

    public boolean isEmpty() {
        return front == null;
    }
}
```

