import java.util.*;

public class RawFragmentsSupplier {
    private Map<String, Integer> rawFragments;

    public RawFragmentsSupplier(Map<String, Integer> rawFragments) {
        this.rawFragments = rawFragments;
    }

    public Set<String> sortRawFragmentsByQuantity() {
        List<Map.Entry<String, Integer>> entryList = new ArrayList<>(rawFragments.entrySet());
        entryList.sort((e1, e2) -> e2.getValue().compareTo(e1.getValue())); // Sort by value in descending order
        Set<String> sortedFragments = new LinkedHashSet<>();
        for (Map.Entry<String, Integer> entry : entryList) {
            sortedFragments.add(entry.getKey());
        }
        return sortedFragments;
    }
}
```

The `sortRawFragmentsByQuantity` method first converts the map entries to a list, then sorts the list based on the values (quantities) in descending order using a custom comparator. Finally, it creates a linked hash set to maintain the order of insertion and adds the sorted raw fragments to the set before returning it.

