import java.util.ArrayList;
import java.util.List;

public class ConfigManager<T> {
    private List<ConfigChangeListener<T>> listeners;

    public ConfigManager() {
        this.listeners = new ArrayList<>();
    }

    public ConfigChangeListener.ListenerRegistration addChangeListener(ConfigChangeListener<T> listener) {
        listeners.add(listener);
        return () -> listeners.remove(listener);
    }

    public void removeChangeListener(ConfigChangeListener.ListenerRegistration registration) {
        registration.unregister();
    }

    public void notifyChange(T newValue) {
        for (ConfigChangeListener<T> listener : listeners) {
            listener.onConfigurationChange(newValue);
        }
    }

    public static void main(String[] args) {
        ConfigManager<String> configManager = new ConfigManager<>();
        ConfigChangeListener<String> listener1 = newValue -> System.out.println("Listener 1: Configuration changed to " + newValue);
        ConfigChangeListener.ListenerRegistration registration1 = configManager.addChangeListener(listener1);
        ConfigChangeListener<String> listener2 = newValue -> System.out.println("Listener 2: Configuration changed to " + newValue);
        ConfigChangeListener.ListenerRegistration registration2 = configManager.addChangeListener(listener2);

        configManager.notifyChange("new value");

        configManager.removeChangeListener(registration1);

        configManager.notifyChange("another value");
    }
}
```

