public class LongestEqualSubstring {
    public static int longestEqualSubstring(String s) {
        int maxLength = 0;
        int count = 0;
        Map<Integer, Integer> map = new HashMap<>();
        map.put(0, -1);

        for (int i = 0; i < s.length(); i++) {
            count += (s.charAt(i) == '1') ? 1 : -1;
            if (map.containsKey(count)) {
                maxLength = Math.max(maxLength, i - map.get(count));
            } else {
                map.put(count, i);
            }
        }

        return maxLength;
    }

    public static void main(String[] args) {
        String s = "110110000111011111100001001111110101000000";
        System.out.println(longestEqualSubstring(s)); // Output: 14
    }
}
