public class CompostRecipeSerializer extends RecipeSerializer<CompostRecipe> {
    @Override
    public ItemStack getIcon() {
        return new ItemStack(ExNihiloBlocks.BARREL_WOOD.get());
    }

    @Override
    public void write(PacketBuffer buffer, CompostRecipe recipe) {
        JsonObject json = new JsonObject();
        json.addProperty("input", recipe.getInput().getItem().getRegistryName().toString());
        json.addProperty("output", recipe.getOutput().getItem().getRegistryName().toString());
        buffer.writeString(json.toString());
    }

    @Override
    public CompostRecipe read(ResourceLocation recipeId, JsonObject json) {
        if (!json.has("input") || !json.has("output")) {
            throw new IllegalArgumentException("Invalid compost recipe JSON - missing input or output");
        }

        String inputItem = json.get("input").getAsString();
        String outputItem = json.get("output").getAsString();

        ItemStack inputStack = new ItemStack(ForgeRegistryEntry.ITEMS.getValue(new ResourceLocation(inputItem)));
        ItemStack outputStack = new ItemStack(ForgeRegistryEntry.ITEMS.getValue(new ResourceLocation(outputItem)));

        return new CompostRecipe(inputStack, outputStack);
    }
}
