public static int maxDifference(int[] nums) {
    if (nums == null || nums.length < 2) {
        return 0;
    }

    int minNum = nums[0];
    int maxDiff = 0;

    for (int i = 1; i < nums.length; i++) {
        if (nums[i] > minNum) {
            int diff = nums[i] - minNum;
            if (diff > maxDiff) {
                maxDiff = diff;
            }
        } else {
            minNum = nums[i];
        }
    }

    return maxDiff;
}
