    public List<Integer> identifyKneePoints(List<DataPoint> Dd, List<Double> lmxThresholds, List<Integer> lmxIndices) {
        List<Integer> kneeIndices = new ArrayList<>();
        boolean detectKneeForLastLmx = false;

        for (int i = 0; i < lmxIndices.size() - 1; i++) {
            int currentIndex = lmxIndices.get(i);
            double currentThreshold = lmxThresholds.get(i);

            if (currentIndex < Dd.size() - 1) {
                if (detectKneeForLastLmx) {
                    if (Dd.get(currentIndex + 1).getY() < currentThreshold) {
                        kneeIndices.add(currentIndex);
                        detectKneeForLastLmx = false;
                    }
                } else {
                    detectKneeForLastLmx = true;
                }
            }
        }

        return kneeIndices;
    }

