import java.util.concurrent.Callable;
import java.util.concurrent.FutureTask;

public class EvenSumCallable implements Callable<Integer> {
    private int start;
    private int end;

    public EvenSumCallable(int start, int end) {
        this.start = start;
        this.end = end;
    }

    @Override
    public Integer call() {
        int sum = 0;
        for (int i = start; i <= end; i++) {
            if (i % 2 == 0) {
                sum += i;
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        int rangeStart = 1;
        int rangeEnd = 10;

        EvenSumCallable evenSumCallable = new EvenSumCallable(rangeStart, rangeEnd);
        FutureTask<Integer> futureTask = new FutureTask<>(evenSumCallable);

        Thread thread = new Thread(futureTask);
        thread.start();

        try {
            int result = futureTask.get();
            System.out.println("Sum of even numbers in the range " + rangeStart + " to " + rangeEnd + " is: " + result);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

