import javax.crypto.Cipher;
import javax.crypto.SecretKey;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.spec.KeySpec;
import java.util.Base64;
import java.util.Scanner;

public class SecretKeyGenerator {
    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);

        // Step 1: Prompt the user to input a password
        System.out.print("Enter a password: ");
        String password = scanner.nextLine();

        // Step 2: Use PBKDF2 to derive a 256-bit secret key from the provided password
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        KeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 65536, 256);
        SecretKey tmp = factory.generateSecret(spec);
        SecretKey secretKey = new SecretKeySpec(tmp.getEncoded(), "AES");

        // Step 3: Encrypt a sample message using the derived key and AES encryption
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        String originalMessage = "This is a secret message";
        byte[] encryptedMessage = cipher.doFinal(originalMessage.getBytes());

        // Step 4: Decrypt the encrypted message using the derived key and AES decryption
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        byte[] decryptedMessage = cipher.doFinal(encryptedMessage);

        // Step 5: Display the original message, the encrypted message, and the decrypted message
        System.out.println("Original Message: " + originalMessage);
        System.out.println("Encrypted Message: " + Base64.getEncoder().encodeToString(encryptedMessage));
        System.out.println("Decrypted Message: " + new String(decryptedMessage));
    }
}
```

