public class ImageScaler {
    private int originalWidth;
    private int originalHeight;

    public ImageScaler(int originalWidth, int originalHeight) {
        this.originalWidth = originalWidth;
        this.originalHeight = originalHeight;
    }

    public String getScaleConstraint() {
        if (originalWidth > originalHeight) {
            return "landscape";
        } else if (originalHeight > originalWidth) {
            return "portrait";
        } else {
            return "square";
        }
    }

    public String scaleToSize(int targetWidth, int targetHeight) {
        double widthRatio = (double) targetWidth / originalWidth;
        double heightRatio = (double) targetHeight / originalHeight;
        double scaleRatio = Math.min(widthRatio, heightRatio);

        int scaledWidth = (int) (originalWidth * scaleRatio);
        int scaledHeight = (int) (originalHeight * scaleRatio);

        return scaledWidth + " x " + scaledHeight;
    }
}
