        this.success = success;
        this.error = error;
    }

    public static <S, E> Result<S, E> success(S value) {
        return new Result<>(value, null);
    }

    public static <S, E> Result<S, E> failure(E error) {
        return new Result<>(null, error);
    }

    public VoidResult<E> toVoidResult() {
        return new VoidResult<>(error);
    }
}

// VoidResult class representing a result without a value
class VoidResult<E> {
    private final E error;

    public VoidResult(E error) {
        this.error = error;
    }

    public void consumeEither(Runnable successHandler, Consumer<E> errorHandler) {
        if (error != null) {
            errorHandler.accept(error);
        } else {
            successHandler.run();
        }
    }
}

