public class LibraryManagementSystem {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        TreeMap<String, Book> bookTreeMap = new TreeMap<>();
        int endCount = 0;

        while (sc.hasNextLine()) {
            String input = sc.nextLine();
            if (endCount == 2)  // EOF Character
                break;
            if (input.contains("END") && sc.hasNextLine()) {
                endCount++;
                continue;
            } else if (input.contains("END") && !sc.hasNextLine()) {
                endCount++;
                continue;
            } else if (input.contains("BORROW")) {
                String[] s = input.split("BORROW");
                bookTreeMap.put(s[1].trim(), new Book(true));
            } else if (input.contains("RETURN")) {
                String[] s = input.split("RETURN");
                bookTreeMap.get(s[1].trim()).setIsBookBorrowed(false);
            }
        }

        // Print the borrowing status of each book
        for (String title : bookTreeMap.keySet()) {
            System.out.println("Book Title: " + title + ", Borrowed: " + bookTreeMap.get(title).getIsBookBorrowed());
        }
    }
}
```

