public static double[] calculateAverage(float[][] testCases) {
    double[] averages = new double[testCases.length];
    for (int i = 0; i < testCases.length; i++) {
        float a = testCases[i][0];
        float b = testCases[i][1];
        float min = testCases[i][2];
        float max = testCases[i][3];

        if (a >= min && a <= max && !Float.isNaN(a)) {
            if (b >= min && b <= max && !Float.isNaN(b)) {
                averages[i] = (a + b) / 2.0;
            } else {
                averages[i] = a;
            }
        } else if (b >= min && b <= max && !Float.isNaN(b)) {
            averages[i] = b;
        } else {
            averages[i] = Double.NaN;
        }
    }
    return averages;
}
