import java.util.Collection;
import java.util.Map;
import java.util.stream.Collectors;

public class JsonSerialization {

    public static String toJsonString(Object object) {
        if (object == null) {
            return "null";
        } else if (object instanceof String) {
            return "\"" + escapeString((String) object) + "\"";
        } else if (object instanceof Number || object instanceof Boolean) {
            return object.toString();
        } else if (object.getClass().isArray()) {
            return arrayToJsonString(object);
        } else if (object instanceof Collection) {
            return collectionToJsonString((Collection<?>) object);
        } else if (object instanceof Map) {
            return mapToJsonString((Map<?, ?>) object);
        } else {
            return objectToJsonString(object);
        }
    }

    private static String escapeString(String input) {
        return input
                .replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\b", "\\b")
                .replace("\f", "\\f")
                .replace("\n", "\\n")
                .replace("\r", "\\r")
                .replace("\t", "\\t");
    }

    private static String arrayToJsonString(Object array) {
        StringBuilder builder = new StringBuilder("[");
        int length = java.lang.reflect.Array.getLength(array);
        for (int i = 0; i < length; i++) {
            if (i > 0) {
                builder.append(",");
            }
            builder.append(toJsonString(java.lang.reflect.Array.get(array, i)));
        }
        builder.append("]");
        return builder.toString();
    }

    private static String collectionToJsonString(Collection<?> collection) {
        return "[" + collection.stream()
                .map(JsonSerialization::toJsonString)
                .collect(Collectors.joining(",")) + "]";
    }

    private static String mapToJsonString(Map<?, ?> map) {
        return "{" + map.entrySet().stream()
                .map(entry -> "\"" + escapeString(entry.getKey().toString()) + "\":" + toJsonString(entry.getValue()))
                .collect(Collectors.joining(",")) + "}";
    }

    private static String objectToJsonString(Object object) {
        // Use the provided JsonMapper for custom object serialization
        return JsonMapper.getInstance().toJson(object);
    }
}
