class JobInvocation {
    private String methodName;
    private String className;
    private String parameters;

    public JobInvocation(String methodName, String className, String parameters) {
        this.methodName = methodName;
        this.className = className;
        this.parameters = parameters;
    }

    public String getMethodName() {
        return methodName;
    }

    public String getClassName() {
        return className;
    }

    public String getParameters() {
        return parameters;
    }
}

public class JobDecoder {
    public JobInvocation decodeJobInvocation(String codeSnippet) {
        Pattern pattern = Pattern.compile("\\s+(\\d+)\\s+(\\d+):(\\w+)\\s+#(\\d+)\\s+<Method (\\w+)\\.(\\w+)\\((\\w+)\\)>");
        Matcher matcher = pattern.matcher(codeSnippet);

        if (matcher.find()) {
            String methodName = matcher.group(6);
            String className = matcher.group(5);
            String parameters = matcher.group(7);
            return new JobInvocation(methodName, className, parameters);
        } else {
            return null; // Handle invalid input
        }
    }

    public static void main(String[] args) {
        JobDecoder jobDecoder = new JobDecoder();
        String codeSnippet = "//    2    4:invokevirtual   #30  <Method JobInvocation$Builder JobCoder.decode(Bundle)>";
        JobInvocation jobInvocation = jobDecoder.decodeJobInvocation(codeSnippet);
        if (jobInvocation != null) {
            System.out.println("Method Name: " + jobInvocation.getMethodName());
            System.out.println("Class Name: " + jobInvocation.getClassName());
            System.out.println("Parameters: " + jobInvocation.getParameters());
        } else {
            System.out.println("Invalid input");
        }
    }
}
