public String longestSubstringWithTwoDistinct(String T) {
    if (T == null || T.length() == 0) {
        return "";
    }

    int[] poses = new int[128];
    Map<Character, Integer> maxPos = new HashMap<>();
    int start = 0, end = 0, maxLen = 0, maxStart = 0;

    for (int i = 0; i < T.length(); i++) {
        char c = T.charAt(i);
        maxPos.put(c, i);
        poses[c] = i;

        if (maxPos.size() > 2) {
            int minPos = Collections.min(maxPos.values());
            maxPos.remove(T.charAt(minPos));
            start = minPos + 1;
        }

        if (i - start + 1 > maxLen) {
            maxLen = i - start + 1;
            maxStart = start;
        }
    }

    return T.substring(maxStart, maxStart + maxLen);
}
