```java
import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.element.Element;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import javax.tools.JavaFileObject;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;

@SupportedAnnotationTypes("cyan.tool.kit.UniqueId")
public class UniqueIdAnnotationProcessor extends AbstractProcessor {

    private Set<String> generatedClassNames = new HashSet<>();
    private int uniqueIdCounter = 0;

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(UniqueId.class)) {
            if (element instanceof TypeElement) {
                TypeElement typeElement = (TypeElement) element;
                String className = typeElement.getQualifiedName().toString();
                String generatedClassName = className + "_" + uniqueIdCounter;
                if (generatedClassNames.contains(generatedClassName)) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Generated class name " + generatedClassName + " already exists");
                } else {
                    generatedClassNames.add(generatedClassName);
                    generateClassWithUniqueId(typeElement, generatedClassName);
                    uniqueIdCounter++;
                }
            }
        }
        return true;
    }

    private void generateClassWithUniqueId(TypeElement typeElement, String generatedClassName) {
        try {
            JavaFileObject fileObject = processingEnv.getFiler().createSourceFile(generatedClassName, typeElement);
            try (PrintWriter writer = new PrintWriter(fileObject.openWriter())) {
                writer.println("public class " + generatedClassName + " {}");
            }
        } catch (IOException e) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error creating source file for " + generatedClassName + ": " + e.getMessage());
        }
    }
}
```

In this solution, we create an annotation processor `UniqueIdAnnotationProcessor` that extends `AbstractProcessor`. We override the `process` method to process classes annotated with `@UniqueId`. For each annotated class, we generate a unique identifier and append it to the class name. We use a `Set` to keep track of generated class names and ensure uniqueness. The generated class is created using the `Filer` provided by the processing environment. If a generated class name already exists, an error message is printed.

