public class NamespaceManager {
    private Map<String, String> namespaces;

    public NamespaceManager() {
        this.namespaces = new HashMap<>();
    }

    // Method to add a new namespace
    public void addNamespace(String parentNamespace, String newNamespace) {
        String fullNamespace = getFullNamespace(parentNamespace) + newNamespace;
        namespaces.put(newNamespace, fullNamespace);
    }

    // Method to retrieve the full namespace path for a given namespace
    public String getFullNamespace(String namespace) {
        return namespaces.getOrDefault(namespace, "") + ".";
    }

    // Method to retrieve all sub-namespaces for a given namespace
    public Set<String> getSubNamespaces(String namespace) {
        String prefix = getFullNamespace(namespace);
        return namespaces.entrySet().stream()
                .filter(entry -> entry.getValue().startsWith(prefix))
                .map(Map.Entry::getKey)
                .collect(Collectors.toSet());
    }

    public static void main(String[] args) {
        NamespaceManager manager = new NamespaceManager();
        manager.addNamespace("", "root.");
        manager.addNamespace("root.", "data.");
        manager.addNamespace("root.data.", "subdata.");

        System.out.println(manager.getFullNamespace("root.data")); // Output: root.data.
        System.out.println(manager.getSubNamespaces("root")); // Output: [root., root.data., root.data.subdata.]
    }
}
```

