import org.apache.commons.collections4.IteratorUtils;

public class CollectionProcessor {
    public static <T> Optional<T> processCollection(Collection<T> collection) {
        try {
            if (collection.isEmpty()) {
                return Optional.empty();
            } else if (collection.size() == 1) {
                return Optional.of(collection.iterator().next());
            } else {
                return Optional.of(IteratorUtils.get(collection.iterator(), 1));
            }
        } catch (Exception e) {
            // Handle any potential exceptions that may occur during processing
            System.err.println("An error occurred while processing the collection: " + e.getMessage());
            return Optional.empty();
        }
    }
}
