class Room {
    private long id;
    private String roomNum;
    private Map<LocalDate, BookingInfo> bookings;

    public Room(long id, String roomNum) {
        this.id = id;
        this.roomNum = roomNum;
        this.bookings = new HashMap<>();
    }

    public void setId(long id) {
        this.id = id;
    }

    public void setRoomNum(String roomNum) {
        this.roomNum = roomNum;
    }

    public String getContent() {
        return "Room Number: " + roomNum;
    }

    public void bookRoom(String guestName, LocalDate checkInDate, LocalDate checkOutDate) {
        for (LocalDate date = checkInDate; date.isBefore(checkOutDate); date = date.plusDays(1)) {
            if (bookings.containsKey(date)) {
                throw new IllegalArgumentException("Room already booked for the specified period");
            }
        }
        BookingInfo bookingInfo = new BookingInfo(guestName, checkInDate, checkOutDate);
        bookings.put(checkInDate, bookingInfo);
    }

    public boolean isBooked(LocalDate date) {
        return bookings.containsKey(date);
    }

    private static class BookingInfo {
        private String guestName;
        private LocalDate checkInDate;
        private LocalDate checkOutDate;

        public BookingInfo(String guestName, LocalDate checkInDate, LocalDate checkOutDate) {
            this.guestName = guestName;
            this.checkInDate = checkInDate;
            this.checkOutDate = checkOutDate;
        }
    }
}

class Hotel {
    private Map<Long, Room> rooms;

    public Hotel() {
        this.rooms = new HashMap<>();
    }

    public void addRoom(Room room) {
        rooms.put(room.id, room);
    }

    public void bookRoom(long roomId, String guestName, LocalDate checkInDate, LocalDate checkOutDate) {
        Room room = rooms.get(roomId);
        if (room == null) {
            throw new IllegalArgumentException("Room not found");
        }
        room.bookRoom(guestName, checkInDate, checkOutDate);
    }

    public boolean isRoomBooked(long roomId, LocalDate date) {
        Room room = rooms.get(roomId);
        if (room == null) {
            throw new IllegalArgumentException("Room not found");
        }
        return room.isBooked(date);
    }
}
```

