import org.hamcrest.Description;
import org.hamcrest.TypeSafeMatcher;

public class LogErrorMatcher extends TypeSafeMatcher<String> {
    @Override
    protected boolean matchesSafely(String logMessage) {
        if (logMessage.startsWith("ERROR: ")) {
            String errorMessage = logMessage.substring(7); // Remove "ERROR: " prefix
            if (errorMessage.matches("ERR-\\d{4}.*")) {
                return true; // Valid error message format
            }
        }
        return false; // Invalid or non-error message
    }

    @Override
    public void describeTo(Description description) {
        description.appendText("The log should not contain unexpected errors.");
    }
}
```

