public class HttpRequestParser {
    public static HttpRequest parse(InputStream is, boolean keepAlive) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(is));
        String requestLine = reader.readLine();
        String[] parts = requestLine.split(" ");
        if (parts.length == 3) {
            String method = parts[0];
            String requestURI = parts[1];
            String httpVersion = parts[2];
            return new HttpRequest(method, requestURI, httpVersion);
        } else {
            throw new IllegalArgumentException("Invalid HTTP request format");
        }
    }
}
