import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;

class Injector {
    private final Map<Class<?>, Supplier<?>> bindings = new HashMap<>();

    private Injector() {
    }

    static Injector of(Module module) {
        Injector injector = new Injector();
        module.configureBindings(injector.bindings);
        return injector;
    }

    <T> T getInstance(Class<T> type) {
        @SuppressWarnings("unchecked")
        Supplier<T> supplier = (Supplier<T>) bindings.get(type);
        if (supplier == null) {
            throw new RuntimeException("No binding found for type: " + type);
        }
        return supplier.get();
    }
}

class Module {
    private final Map<Class<?>, Supplier<?>> bindings = new HashMap<>();

    <T> BindingBuilder<T> bind(Class<T> type) {
        return new BindingBuilder<>(type, bindings);
    }

    void configureBindings(Map<Class<?>, Supplier<?>> injectorBindings) {
        injectorBindings.putAll(bindings);
    }
}

class BindingBuilder<T> {
    private final Class<T> type;
    private final Map<Class<?>, Supplier<?>> bindings;

    BindingBuilder(Class<T> type, Map<Class<?>, Supplier<?>> bindings) {
        this.type = type;
        this.bindings = bindings;
    }

    void to(Supplier<T> supplier) {
        bindings.put(type, supplier);
    }
}
```

This solution provides a simple implementation of a dependency injection framework in Java. The `Injector` class is responsible for managing bindings and providing instances of the bound types. The `Module` class allows for configuring bindings, and the `BindingBuilder` class is used to specify the concrete implementation for a given type. The `Supplier` functional interface is used to provide instances of the bound types.

