import java.util.*;

public class DistributedNodeManager<N> implements NodeManager<N> {
    private Map<NodeType, Collection<N>> nodesByType;

    public DistributedNodeManager() {
        this.nodesByType = new HashMap<>();
        for (NodeType type : NodeType.values()) {
            nodesByType.put(type, new ArrayList<>());
        }
    }

    @Override
    public Collection<N> getNodes(NodeType type) {
        return nodesByType.getOrDefault(type, Collections.emptyList());
    }

    @Override
    public Collection<N> getNodes() {
        List<N> allNodes = new ArrayList<>();
        for (Collection<N> nodes : nodesByType.values()) {
            allNodes.addAll(nodes);
        }
        return allNodes;
    }

    // Additional methods to manage nodes in the distributed system
    public void addNode(NodeType type, N node) {
        nodesByType.computeIfAbsent(type, k -> new ArrayList<>()).add(node);
    }

    public void removeNode(NodeType type, N node) {
        nodesByType.getOrDefault(type, Collections.emptyList()).remove(node);
    }
}
