import java.math.BigInteger;
import java.util.HashMap;
import java.util.Map;

public class DCN {
    private Map<Integer, String> users;
    private Map<Integer, BigInteger> exchangeAccounts;
    private Map<Integer, Map<Integer, BigInteger>> userAccounts;

    public DCN() {
        this.users = new HashMap<>();
        this.exchangeAccounts = new HashMap<>();
        this.userAccounts = new HashMap<>();
    }

    public int user_create() {
        int userId = generateUserId();
        users.put(userId, "User" + userId);
        userAccounts.put(userId, new HashMap<>());
        return userId;
    }

    public void exchange_deposit(int userId, int exchangeId, BigInteger amount) {
        if (users.containsKey(userId)) {
            exchangeAccounts.put(exchangeId, exchangeAccounts.getOrDefault(exchangeId, BigInteger.ZERO).add(amount));
        } else {
            throw new IllegalArgumentException("User does not exist");
        }
    }

    public void user_deposit(int userId, int accountId, BigInteger amount) {
        if (users.containsKey(userId)) {
            Map<Integer, BigInteger> accounts = userAccounts.get(userId);
            accounts.put(accountId, accounts.getOrDefault(accountId, BigInteger.ZERO).add(amount));
        } else {
            throw new IllegalArgumentException("User does not exist");
        }
    }

    public void transfer_to_session(int userId, int sessionId, BigInteger amount) {
        if (users.containsKey(userId)) {
            Map<Integer, BigInteger> accounts = userAccounts.get(userId);
            BigInteger balance = accounts.getOrDefault(sessionId, BigInteger.ZERO);
            if (balance.compareTo(amount) >= 0) {
                accounts.put(sessionId, balance.subtract(amount));
            } else {
                throw new IllegalArgumentException("Insufficient balance");
            }
        } else {
            throw new IllegalArgumentException("User does not exist");
        }
    }

    private int generateUserId() {
        return users.size() + 1;
    }
}
```

