```java
public class CommentAnalyzer {
    public static void main(String[] args) {
        String sourceCode = "/* This is a\n   multi-line\n   comment */\n" +
                            "// This is a single-line comment\n" +
                            "/** This is a Javadoc comment */\n" +
                            "public class Example {\n" +
                            "    // Another single-line comment\n" +
                            "    public void method() {\n" +
                            "        // Yet another single-line comment\n" +
                            "    }\n" +
                            "}";
        int[] commentCounts = countComments(sourceCode);
        System.out.println("Single-line comments: " + commentCounts[0]);
        System.out.println("Multi-line comments: " + commentCounts[1]);
        System.out.println("Javadoc comments: " + commentCounts[2]);
    }

    public static int[] countComments(String sourceCode) {
        int singleLineCount = 0;
        int multiLineCount = 0;
        int javadocCount = 0;

        String[] lines = sourceCode.split("\n");
        boolean inMultiLineComment = false;

        for (String line : lines) {
            line = line.trim();
            if (line.startsWith("//")) {
                singleLineCount++;
            } else if (line.startsWith("/*")) {
                multiLineCount++;
                inMultiLineComment = true;
            } else if (line.startsWith("*/")) {
                inMultiLineComment = false;
                multiLineCount++;
            } else if (line.startsWith("/**") || (inMultiLineComment && line.contains("*/"))) {
                javadocCount++;
            } else if (inMultiLineComment) {
                multiLineCount++;
            }
        }

        return new int[]{singleLineCount, multiLineCount, javadocCount};
    }
}
```

