import java.util.Arrays;

public class StatisticalAnalysis {
    double lastDelimiterStdDev = Double.POSITIVE_INFINITY;
    byte lastDelimiterPriority = Byte.MIN_VALUE;
    double lastDelimiterMean = 0;
    double lineLengthStdDev = 0;

    public void updateStatistics(int[] dataPoints) {
        // Calculate the standard deviation of the dataPoints array
        double sum = 0;
        for (int num : dataPoints) {
            sum += num;
        }
        double mean = sum / dataPoints.length;
        double sumOfSquares = 0;
        for (int num : dataPoints) {
            sumOfSquares += Math.pow(num - mean, 2);
        }
        double variance = sumOfSquares / dataPoints.length;
        double stdDev = Math.sqrt(variance);

        // Update lastDelimiterStdDev if the calculated lineLengthStdDev is less
        if (stdDev < lastDelimiterStdDev) {
            lastDelimiterStdDev = stdDev;
        }

        // Update lastDelimiterPriority with the priority of the current data point
        for (int i = 0; i < dataPoints.length; i++) {
            if (dataPoints[i] < 0) {
                lastDelimiterPriority = (byte) i;
                break;
            }
        }

        // Calculate the mean of the dataPoints array and store the result in lastDelimiterMean
        double sumOfDataPoints = 0;
        for (int num : dataPoints) {
            sumOfDataPoints += num;
        }
        lastDelimiterMean = sumOfDataPoints / dataPoints.length;

        // Update lineLengthStdDev with the calculated standard deviation
        lineLengthStdDev = stdDev;
    }
}
```

