import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.LayoutManager;
import java.util.ArrayList;
import java.util.List;

public class CircularLayoutManager implements LayoutManager {
    private List<Component> components = new ArrayList<>();

    @Override
    public void addLayoutComponent(String name, Component comp) {
        components.add(comp);
    }

    @Override
    public void removeLayoutComponent(Component comp) {
        components.remove(comp);
    }

    @Override
    public Dimension preferredLayoutSize(Container parent) {
        return calculateLayoutSize(parent);
    }

    @Override
    public Dimension minimumLayoutSize(Container parent) {
        return calculateLayoutSize(parent);
    }

    @Override
    public void layoutContainer(Container parent) {
        int centerX = parent.getWidth() / 2;
        int centerY = parent.getHeight() / 2;
        int radius = Math.min(parent.getWidth(), parent.getHeight()) / 3;

        double angleStep = 2 * Math.PI / components.size();
        double angle = 0;

        for (Component component : components) {
            int x = (int) (centerX + radius * Math.cos(angle) - component.getWidth() / 2);
            int y = (int) (centerY + radius * Math.sin(angle) - component.getHeight() / 2);
            component.setBounds(x, y, component.getWidth(), component.getHeight());
            angle += angleStep;
        }
    }

    private Dimension calculateLayoutSize(Container parent) {
        int maxWidth = 0;
        int maxHeight = 0;

        for (Component component : components) {
            maxWidth = Math.max(maxWidth, component.getPreferredSize().width);
            maxHeight = Math.max(maxHeight, component.getPreferredSize().height);
        }

        return new Dimension(maxWidth * 2, maxHeight * 2);
    }
}
