```java
public <T> T convertValue(Object value, Class<T> targetType) {
    if (value == null) {
        if (targetType.isPrimitive()) {
            throw new UnsupportedOperationException("Cannot convert null to primitive type " + targetType.getSimpleName());
        }
        return null;
    }

    if (targetType.isInstance(value)) {
        return targetType.cast(value);
    }

    if (targetType == String.class) {
        return (T) value.toString();
    }

    if (targetType == Integer.class) {
        if (value instanceof String) {
            try {
                return (T) (Integer) Integer.parseInt((String) value);
            } catch (NumberFormatException e) {
                throw new UnsupportedOperationException("Cannot convert " + value.getClass() + " to " + targetType.getSimpleName());
            }
        }
    }

    if (targetType == Double.class) {
        if (value instanceof String) {
            try {
                return (T) (Double) Double.parseDouble((String) value);
            } catch (NumberFormatException e) {
                throw new UnsupportedOperationException("Cannot convert " + value.getClass() + " to " + targetType.getSimpleName());
            }
        }
    }

    throw new UnsupportedOperationException("Cannot convert " + value.getClass() + " to " + targetType.getSimpleName());
}
