import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;

public class DependencyInjectionFramework {
    private Map<Class<?>, Object> singletonInstances = new HashMap<>();

    public void registerSingleton(Class<?> clazz) {
        if (clazz.isAnnotationPresent(Singleton.class)) {
            try {
                Object instance = clazz.getDeclaredConstructor().newInstance();
                singletonInstances.put(clazz, instance);
                injectDependencies(instance);
                callPostConstructMethod(instance);
            } catch (InstantiationException | IllegalAccessException | InvocationTargetException | NoSuchMethodException e) {
                e.printStackTrace();
            }
        }
    }

    private void injectDependencies(Object instance) {
        for (Method method : instance.getClass().getDeclaredMethods()) {
            if (method.isAnnotationPresent(Inject.class)) {
                Class<?>[] parameterTypes = method.getParameterTypes();
                Object[] dependencies = new Object[parameterTypes.length];
                for (int i = 0; i < parameterTypes.length; i++) {
                    dependencies[i] = singletonInstances.get(parameterTypes[i]);
                }
                try {
                    method.invoke(instance, dependencies);
                } catch (IllegalAccessException | InvocationTargetException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    private void callPostConstructMethod(Object instance) {
        for (Method method : instance.getClass().getDeclaredMethods()) {
            if (method.isAnnotationPresent(PostConstruct.class)) {
                try {
                    method.invoke(instance);
                } catch (IllegalAccessException | InvocationTargetException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    public void destroySingletons() {
        for (Object instance : singletonInstances.values()) {
            callPreDestroyMethod(instance);
        }
        singletonInstances.clear();
    }

    private void callPreDestroyMethod(Object instance) {
        for (Method method : instance.getClass().getDeclaredMethods()) {
            if (method.isAnnotationPresent(PreDestroy.class)) {
                try {
                    method.invoke(instance);
                } catch (IllegalAccessException | InvocationTargetException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    public static void main(String[] args) {
        DependencyInjectionFramework framework = new DependencyInjectionFramework();
        framework.registerSingleton(ServiceA.class);
        framework.registerSingleton(ServiceB.class);
        ServiceA serviceA = (ServiceA) framework.singletonInstances.get(ServiceA.class);
        serviceA.invokeServiceBMethod();
        framework.destroySingletons();
    }
}

@Singleton
class ServiceA {
    @Inject
    private ServiceB serviceB;

    @PostConstruct
    public void init() {
        System.out.println("ServiceA initialized");
    }

    @PreDestroy
    public void destroy() {
        System.out.println("ServiceA destroyed");
    }

    public void invokeServiceBMethod() {
        serviceB.doSomething();
    }
}

@Singleton
class ServiceB {
    @PostConstruct
    public void init() {
        System.out.println("ServiceB initialized");
    }

    @PreDestroy
    public void destroy() {
        System.out.println("ServiceB destroyed");
    }

    public void doSomething() {
        System.out.println("ServiceB doing something");
    }
}
```

In this solution, we create a `DependencyInjectionFramework` class that manages the lifecycle of singleton instances and their dependencies. We use reflection to scan for annotations and invoke methods accordingly. The `main` method demonstrates the usage of the framework by registering singleton classes, resolving dependencies, and calling lifecycle methods. The `ServiceA` and `ServiceB` classes showcase the usage of annotations for dependency injection and lifecycle management.

