import java.util.*;

public class StreamManager {
  private Map<String, List<String>> streamTopicsMap;

  public StreamManager() {
    this.streamTopicsMap = new HashMap<>();
  }

  /**
   * Initialize stream topic map.
   */
  private void initializeStreamTopicMap() {
    List<String> penServicesEventsTopics = new ArrayList<>();
    penServicesEventsTopics.add("PEN_SERVICES_EVENTS_TOPIC");
    this.streamTopicsMap.put("PEN_SERVICES_EVENTS", penServicesEventsTopics);
  }

  /**
   * Subscribe to a given topic.
   * 
   * @param topic       the topic to subscribe to
   * @param subscriber  the subscriber's identifier
   */
  public void subscribeToTopic(String topic, String subscriber) {
    if (streamTopicsMap.containsKey(topic)) {
      List<String> subscribers = streamTopicsMap.get(topic);
      subscribers.add(subscriber);
      streamTopicsMap.put(topic, subscribers);
    } else {
      List<String> newSubscribers = new ArrayList<>();
      newSubscribers.add(subscriber);
      streamTopicsMap.put(topic, newSubscribers);
    }
  }
}
```

