import android.widget.Button;

public class CustomFontButton extends Button {

    private Typeface customTypeface;

    public CustomFontButton(Context context, AttributeSet attrs) {
        super(context, attrs);
        initTypeface(context, attrs);
    }

    private void initTypeface(Context context, AttributeSet attrs) {
        // Retrieve the custom typeface attribute from the XML layout
        TypedArray a = context.obtainStyledAttributes(attrs, R.styleable.CustomFontButton);
        String typefacePath = a.getString(R.styleable.CustomFontButton_customTypeface);
        a.recycle();

        // Load the custom typeface
        customTypeface = Typeface.createFromAsset(context.getAssets(), typefacePath);

        // Set the initial typeface for the button
        setTypeface(customTypeface);
    }

