import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.ArrayList;

public class HomographIndexGenerator {
    public Map<String, List<String>> generateHomographIndex(List<String> words) {
        Map<String, List<String>> homographIndex = new HashMap<>();

        for (String word : words) {
            homographIndex.putIfAbsent(word, new ArrayList<>());
        }

        homographIndex.get("lead").add("to guide");
        homographIndex.get("lead").add("metal");

        homographIndex.get("bass").add("low-frequency sound");
        homographIndex.get("bass").add("fish");

