    @Override
    public boolean isSupported(Object object) {
        return object instanceof OptionalLong;
    }

    @Override
    public SerializerObject serialize(SerializeData<OptionalLong> serializeData) {
        SerializerObject serializerObject = new SerializerObject(serializeData.object, serializeData.object.isPresent());
