public static void setExpireHeaders(
        HttpServletResponse response,
        Integer year, Integer month
) {
    if (month == null) {
        response.setDateHeader("Expires", System.currentTimeMillis() + 60 * 1000);
        response.setDateHeader("Last-Modified", System.currentTimeMillis());
    } else {
        // Calculate the expiration date based on the given year and month
        Calendar calendar = Calendar.getInstance();
        calendar.set(Calendar.YEAR, year);
        calendar.set(Calendar.MONTH, month - 1); // Month is 0-based in Calendar
        calendar.set(Calendar.DAY_OF_MONTH, calendar.getActualMaximum(Calendar.DAY_OF_MONTH));
        calendar.set(Calendar.HOUR_OF_DAY, 23);
        calendar.set(Calendar.MINUTE, 59);
        calendar.set(Calendar.SECOND, 59);
        long expirationDate = calendar.getTimeInMillis();

        // Set the "Expires" header to the calculated expiration date
        response.setDateHeader("Expires", expirationDate);
        response.setDateHeader("Last-Modified", System.currentTimeMillis());
    }
