            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            String command = reader.readLine();

            // Execute the specified command using ProcessBuilder
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            Process process = processBuilder.start();

            // Capture the output of the command and display it to the console
            BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            System.out.println("Command output:");
            while ((line = outputReader.readLine()) != null) {
                System.out.println(line);
            }

            // Capture the exit code of the command and print it to the console
            int exitCode = process.waitFor();
            System.out.println("Exit code: " + exitCode);

        } catch (IOException e) {
            System.err.println("Error executing the command: " + e.getMessage());
        } catch (InterruptedException e) {
            System.err.println("Error waiting for the command to finish: " + e.getMessage());
        }
    }
}
