@Override
public Component getComponentAfter(Container focusCycleRoot, Component a) {
    int index = -1;
    for (int i = 0; i < buttons.length; i++) {
        if (buttons[i] == a) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        int nextIndex = (index + 1) % buttons.length;
        return buttons[nextIndex];
    } else {
        return buttons[0]; // If the given component is not found, return the first button
    }
}
```

