import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

public class ConfigParser {
    public Map<String, Object> parseDefaultConfig(Class<?> configClass) {
        Map<String, Object> configMap = new HashMap<>();
        Field[] fields = configClass.getDeclaredFields();
        for (Field field : fields) {
            if (java.lang.reflect.Modifier.isStatic(field.getModifiers()) && java.lang.reflect.Modifier.isFinal(field.getModifiers())) {
                try {
                    field.setAccessible(true);
                    configMap.put(field.getName(), field.get(null));
                } catch (IllegalAccessException e) {
                    // Handle exception as per requirement
                }
            }
        }
        return configMap;
    }

