        itemLore = cs.getStringList("item-lore");
        costList = new ArrayList<>();
        ConfigurationSection costsSection = cs.getConfigurationSection("costs");
        for (String costKey : costsSection.getKeys(false)) {
            if (!costsSection.isConfigurationSection(costKey)) {
                String material = costKey; // Assuming material is a string attribute
                double repairCost = costsSection.getDouble(costKey);
                costList.add(new MythicRepairCost(costKey, material, repairCost));
            }
        }
