        double totalCost = 0;
        for (String lore : itemLore) {
            for (MythicRepairCost cost : costList) {
                if (lore.contains(cost.getMaterial())) {
                    totalCost += cost.getRepairCost();
                }
            }
        }
        return totalCost;
    }

