import java.util.ArrayList;
import java.util.List;

public class LoggableSearchChain {
    protected List<TeiDocument> results = new ArrayList<>();

    public List<TeiDocument> filterResultsByCriteria(String criteria) {
        List<TeiDocument> filteredResults = new ArrayList<>();
        if (criteria.equals("loggable")) {
            for (TeiDocument document : results) {
                if (document.isLoggable()) {
                    filteredResults.add(document);
                }
            }
        } else if (criteria.equals("non-loggable")) {
            for (TeiDocument document : results) {
                if (!document.isLoggable()) {
                    filteredResults.add(document);
                }
            }
        } else if (criteria.equals("all")) {
            filteredResults.addAll(results);
        }
        return filteredResults;
    }
}
```

