public class RobotDistanceCalculator {
    public static int calculateDistance(String movements) {
        if (movements == null || movements.isEmpty()) {
            return 0; // Return 0 for empty or null input
        }

        int distanceX = 0; // Distance traveled in the horizontal (left-right) direction
        int distanceY = 0; // Distance traveled in the vertical (up-down) direction

        for (char movement : movements.toCharArray()) {
            switch (movement) {
                case 'U':
                    distanceY++;
                    break;
                case 'D':
                    distanceY--;
                    break;
                case 'L':
                    distanceX--;
                    break;
                case 'R':
                    distanceX++;
                    break;
                // Handle invalid movement characters if needed
            }
        }

        // Calculate total distance using Manhattan distance formula
        return Math.abs(distanceX) + Math.abs(distanceY);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(calculateDistance("UDLR"));  // Output: 0
        System.out.println(calculateDistance("ULDR"));  // Output: 2
        System.out.println(calculateDistance(null));    // Output: 0
        System.out.println(calculateDistance(""));      // Output: 0
    }
}
