import javax.servlet.http.HttpServletRequest;

public class ClientIPAddressExtractor {
    public String getClientIPAddress(HttpServletRequest request) {
        String clientIP = request.getHeader("X-Forwarded-For");

        if (clientIP != null && clientIP.length() > 0) {
            // The "X-Forwarded-For" header is present, extract the first IP address
            return clientIP.split(",")[0].trim();
        } else {
            clientIP = request.getHeader("X-Real-IP");
            if (clientIP != null && clientIP.length() > 0) {
                // The "X-Real-IP" header is present, return its value
                return clientIP;
            } else {
                // Both headers are absent, retrieve the client's IP address using request.getRemoteAddr()
                return request.getRemoteAddr();
            }
        }
    }
}
```

