public class VelocityXmlTransformationTask extends Task {
    private String inputXmlFile;
    private String velocityTemplateFile;
    private String outputXmlFile;

    public void setInputXmlFile(String inputXmlFile) {
        this.inputXmlFile = inputXmlFile;
    }

    public void setVelocityTemplateFile(String velocityTemplateFile) {
        this.velocityTemplateFile = velocityTemplateFile;
    }

    public void setOutputXmlFile(String outputXmlFile) {
        this.outputXmlFile = outputXmlFile;
    }

    @Override
    public void execute() throws BuildException {
        if (inputXmlFile == null || velocityTemplateFile == null || outputXmlFile == null) {
            throw new BuildException("Input XML file, Velocity template file, and output file path are required.");
        }

        VelocityEngine velocityEngine = new VelocityEngine();
        velocityEngine.init();

        VelocityContext context = new VelocityContext();
        context.put("inputXmlFile", inputXmlFile);

        Template template = velocityEngine.getTemplate(velocityTemplateFile);

        try (FileWriter fileWriter = new FileWriter(new File(outputXmlFile))) {
            template.merge(context, fileWriter);
        } catch (IOException e) {
            throw new BuildException("Error writing the transformed XML to the output file: " + e.getMessage());
        }
    }
}
