package com.example.app.ourapplication.util;

import java.util.ArrayList;

public class PackageManager {
    public static int countAndroidPackages(ArrayList<String> packageNames) {
        int count = 0;
        for (String packageName : packageNames) {
            if (isValidAndroidPackageName(packageName)) {
                count++;
            }
        }
        return count;
    }

    private static boolean isValidAndroidPackageName(String packageName) {
        String[] segments = packageName.split("\\.");
        for (String segment : segments) {
            if (!isValidSegment(segment)) {
                return false;
            }
        }
        return segments.length > 1;  // At least one segment is required
    }

    private static boolean isValidSegment(String segment) {
        return segment.matches("[a-zA-Z][a-zA-Z0-9_]*");
    }
}
