import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;

public class DateSanitizer {
    private static final String LOGIN_NAME = "loginName";
    private static final String CREATED = "created";
    private static final String LAST_MODIFIED = "lastModified";
    private static final SimpleDateFormat DATE_FORMAT_EN = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");
    private static final SimpleDateFormat FORMATTED_DATE_FORMAT = new SimpleDateFormat("dd/MM/yyyy HH:mm:ss");

    public void sanitizeAndFormatDates(User user) {
        String loginName = user.getAttribute(LOGIN_NAME);
        String created = user.getAttribute(CREATED);
        String modified = user.getAttribute(LAST_MODIFIED);

        try {
            Date parsedCreated = DATE_FORMAT_EN.parse(created);
            Date parsedModified = DATE_FORMAT_EN.parse(modified);

            String formattedCreated = FORMATTED_DATE_FORMAT.format(parsedCreated);
            String formattedModified = FORMATTED_DATE_FORMAT.format(parsedModified);

            user.setAttribute(CREATED, formattedCreated);
            user.setAttribute(LAST_MODIFIED, formattedModified);
        } catch (ParseException e) {
            // Handle parsing exception
            System.err.println("Error parsing dates: " + e.getMessage());
        }
    }
}
