class Node {
    int val;
    Node next;

    public Node(int val) {
        this.val = val;
    }
}

public class DeepCopyLinkedList {
    public Node deepCopy(Node head) {
        if (head == null) {
            return null;
        }

        // Step 1: Create a new weaved list of original and copied nodes.
        Node ptr = head;
        while (ptr != null) {
            // Cloned node
            Node newNode = new Node(ptr.val);

            // Inserting the cloned node just next to the original node.
            newNode.next = ptr.next;
            ptr.next = newNode;
            ptr = newNode.next;
        }

        // Step 2: Adjust the random pointers of the cloned nodes.
        ptr = head;
        while (ptr != null) {
            if (ptr.next != null) {
                ptr.next.next = (ptr.next != null) ? ptr.next.next : null;
            }
            ptr = (ptr.next != null) ? ptr.next.next : null;
        }

        // Step 3: Separate the original and cloned nodes into two separate lists.
        ptr = head;
        Node newHead = head.next;
        Node newPtr = newHead;
        while (ptr != null) {
            ptr.next = (ptr.next != null) ? ptr.next.next : null;
            newPtr.next = (newPtr.next != null) ? newPtr.next.next : null;
            ptr = ptr.next;
            newPtr = newPtr.next;
        }

        return newHead;
    }

    public static void main(String[] args) {
        DeepCopyLinkedList solution = new DeepCopyLinkedList();

        // Example usage
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);

        Node deepCopyHead = solution.deepCopy(head);
        // deepCopyHead now contains the deep copy of the original linked list
    }
}
```

