import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.ProcessingEnvironment;
import javax.lang.model.element.TypeElement;
import javax.lang.model.element.Element;
import javax.lang.model.element.AnnotationMirror;
import javax.lang.model.element.AnnotationValue;
import javax.lang.model.element.ExecutableElement;
import javax.tools.Diagnostic;
import java.util.Set;

public class CustomEndpointProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(CustomEndpoint.class)) {
            if (element.getKind().isClass()) {
                AnnotationMirror annotationMirror = getAnnotationMirror(element, CustomEndpoint.class);
                if (annotationMirror != null) {
                    validateAttributes(annotationMirror, element);
                }
            } else {
                processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "@CustomEndpoint can only be applied to classes", element);
            }
        }
        return true;
    }

    private AnnotationMirror getAnnotationMirror(Element element, Class<?> annotationClass) {
        for (AnnotationMirror annotationMirror : element.getAnnotationMirrors()) {
            if (annotationMirror.getAnnotationType().toString().equals(annotationClass.getCanonicalName())) {
                return annotationMirror;
            }
        }
        return null;
    }

    private void validateAttributes(AnnotationMirror annotationMirror, Element element) {
        validateNonEmptyArrayAttribute(annotationMirror, "params", element);
        validateNonEmptyArrayAttribute(annotationMirror, "headers", element);
        validateNonEmptyArrayAttribute(annotationMirror, "consumes", element);
        validateNonEmptyArrayAttribute(annotationMirror, "produces", element);
    }

    private void validateNonEmptyArrayAttribute(AnnotationMirror annotationMirror, String attributeName, Element element) {
        AnnotationValue attributeValue = getAnnotationValue(annotationMirror, attributeName);
        if (attributeValue != null) {
            Object value = attributeValue.getValue();
            if (value instanceof Object[] && ((Object[]) value).length == 0) {
                processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "@" + CustomEndpoint.class.getSimpleName() + " attribute '" + attributeName + "' cannot be empty", element);
            }
        }
    }

    private AnnotationValue getAnnotationValue(AnnotationMirror annotationMirror, String attributeName) {
        for (ExecutableElement executableElement : annotationMirror.getElementValues().keySet()) {
            if (executableElement.getSimpleName().toString().equals(attributeName)) {
                return annotationMirror.getElementValues().get(executableElement);
            }
        }
        return null;
    }
}
```

