public class RecordProcessor {
    private static final int HEADER_SIZE = 8; // Size of the header in bytes
    private static final int PAYLOAD_LENGTH_OFFSET = 0; // Offset of the payload length within the record

    public static byte[] retrieveRecordPayload(RecordLog log, long recordOffset) {
        int payloadLength = getPayloadLength(log, recordOffset); // Retrieve the payload length
        byte[] payloadData = new byte[payloadLength]; // Create a byte array to store the payload data
        getPayload(log, recordOffset, payloadData); // Retrieve the payload data and store it in the byte array
        return payloadData; // Return the retrieved payload data
    }

    // Existing method to retrieve the payload length
    private static int getPayloadLength(RecordLog log, long recordOffset) {
        return log.pool().getInt(recordOffset + PAYLOAD_LENGTH_OFFSET);
    }

    // Existing method to retrieve the payload data
    private static int getPayload(RecordLog log, long recordOffset, byte[] buffer) {
        MemoryPool pool = log.pool();
        int payloadLength = getPayloadLength(log, recordOffset);
        pool.copyToByteArray(recordOffset + HEADER_SIZE, buffer, 0, payloadLength);
        return payloadLength;
    }
}
```

