import com.liveaction.reactiff.api.server.ReactiveHandler;
import com.liveaction.reactiff.server.ReactiveHttpServer;
import com.liveaction.reactiff.server.context.ExecutionContextService;
import io.netty.handler.codec.http.HttpHeaderNames;
import io.netty.handler.codec.http.HttpResponseStatus;
import reactor.core.publisher.Mono;

public class SimpleHttpServer {

    public static void main(String[] args) {
        ReactiveHttpServer server = ReactiveHttpServer.create("localhost", 8080, new ExecutionContextService());
        server.start(new SimpleHandler());
    }

    static class SimpleHandler implements ReactiveHandler {
        @Override
        public Mono<Void> handle(ServerRequest request, ServerResponse response) {
            if (request.method() == HttpMethod.GET && request.uri().equals("/hello")) {
                return response.addHeader(HttpHeaderNames.CONTENT_TYPE, "text/plain")
                        .status(HttpResponseStatus.OK)
                        .sendString(Mono.just("Hello, World!"));
            } else if (request.method() == HttpMethod.POST && request.uri().equals("/echo")) {
                return response.addHeader(HttpHeaderNames.CONTENT_TYPE, "text/plain")
                        .status(HttpResponseStatus.OK)
                        .send(request.receive().asString());
            } else {
                return response.status(HttpResponseStatus.NOT_FOUND).send();
            }
        }
    }
}
```

In this solution, we create a `ReactiveHttpServer` listening on port 8080 and define a custom `SimpleHandler` implementing the `ReactiveHandler` interface. The handler inspects incoming requests and responds accordingly based on the request method and path. GET requests to "/hello" return "Hello, World!" and POST requests to "/echo" echo the request body. Any other requests result in a 404 Not Found response.

