import java.nio.file.*;
import java.security.*;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;

public class KeyStoreGenerator {
    static KeyStore createKeyStoreFromPemDirectories(Path keyDirPath, String keyExtension, Path certDirPath, String certExtension, char[] password) throws IOException, KeyStoreException, CertificateException, NoSuchAlgorithmException {
        if (!keyDirPath.toFile().isDirectory()) {
            throw new IllegalArgumentException("Key directory path is not a valid directory");
        }

        KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        keyStore.load(null, password);

        try (DirectoryStream<Path> keyFiles = Files.newDirectoryStream(keyDirPath, "*" + keyExtension)) {
            for (Path keyFile : keyFiles) {
                String keyFileName = keyFile.getFileName().toString();
                String certFileName = keyFileName.replace(keyExtension, certExtension);
                Path certFile = certDirPath.resolve(certFileName);

                if (Files.exists(certFile)) {
                    X509Certificate cert = (X509Certificate) CertificateFactory.getInstance("X.509")
                            .generateCertificate(new FileInputStream(certFile.toFile()));
                    keyStore.setCertificateEntry(keyFileName, cert);
                } else {
                    throw new IllegalArgumentException("Certificate file not found for key: " + keyFileName);
                }
            }
        }

        return keyStore;
    }

    public static void main(String[] args) {
        Path keyDirPath = Paths.get("path_to_key_directory");
        String keyExtension = ".key";
        Path certDirPath = Paths.get("path_to_cert_directory");
        String certExtension = ".pem";
        char[] password = "keystore_password".toCharArray();

        try {
            KeyStore keyStore = createKeyStoreFromPemDirectories(keyDirPath, keyExtension, certDirPath, certExtension, password);
            // Use the generated keyStore as needed
        } catch (IOException | KeyStoreException | CertificateException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
