import java.util.HashMap;
import java.util.Map;

public class ConfigParser {
    public Map<String, Object> parseConfig(Map<String, Object> config) {
        Map<String, Object> parsedMap = new HashMap<>();
        if (config.containsKey("bungee-servers") && config.get("bungee-servers") instanceof Map) {
            Map<String, Object> servers = (Map<String, Object>) config.get("bungee-servers");
            for (Map.Entry<String, Object> entry : servers.entrySet()) {
                if (entry.getValue() instanceof String) {
                    String versionString = (String) entry.getValue();
                    ProtocolVersion protocolVersion = ProtocolVersion.getClosest(versionString);
                    parsedMap.put(entry.getKey(), protocolVersion);
                } else {
                    parsedMap.put(entry.getKey(), entry.getValue());
                }
            }
        }
        return parsedMap;
    }
}
