public class EventHandler {
    private Map<String, Set<EventListener>> eventListeners;

    public EventHandler() {
        eventListeners = new HashMap<>();
    }

    public void registerListener(EventListener listener, String eventType) {
        eventListeners.computeIfAbsent(eventType, k -> new HashSet<>()).add(listener);
    }

    public void deregisterListener(EventListener listener, String eventType) {
        eventListeners.getOrDefault(eventType, new HashSet<>()).remove(listener);
    }

    public void dispatchEvent(AWTEvent event) {
        String eventType = event.getEventType();
        Set<EventListener> listeners = eventListeners.getOrDefault(eventType, new HashSet<>());
        for (EventListener listener : listeners) {
            listener.onEvent(event);
        }
    }
}
