    public void generateWinningNumbers() {
        winningNumbers = new int[6];
        Random random = new Random();
        for (int i = 0; i < 6; i++) {
            int num;
            do {
                num = random.nextInt(49) + 1;
            } while (contains(winningNumbers, num));
            winningNumbers[i] = num;
        }
        Arrays.sort(winningNumbers);
    }

