public class HttpHeaderParser {
    public String parseHttpHeader(byte[] tmpByteArr, String encoding) {
        String header = new String(tmpByteArr, encoding);
        return header;
    }

    /**
     * 获取http头部某一项的值
     */
    public String getHeaderValue(String header, String fieldName) {
        String[] headerLines = header.split("\\r?\\n");
        for (String line : headerLines) {
            String[] parts = line.split(": ", 2);
            if (parts.length == 2 && parts[0].equalsIgnoreCase(fieldName)) {
                return parts[1];
            }
        }
        return null;
    }
