class Clock {
    private boolean close;

    public synchronized void open() {
        close = false;
    }

    public synchronized void close() {
        close = true;
    }

    public synchronized boolean isClosed() {
        return close;
    }
}

class OpenThread implements Runnable {
    private Clock clock;
    private int cycles;

    public OpenThread(Clock clock, int cycles) {
        this.clock = clock;
        this.cycles = cycles;
    }

    @Override
    public void run() {
        for (int i = 0; i < cycles; i++) {
            try {
                Thread.sleep(2000);
                clock.open();
                System.out.println("Clock opened");
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}

class CloseThread implements Runnable {
    private Clock clock;
    private int cycles;

    public CloseThread(Clock clock, int cycles) {
        this.clock = clock;
        this.cycles = cycles;
    }

    @Override
    public void run() {
        for (int i = 0; i < cycles; i++) {
            try {
                Thread.sleep(3000);
                clock.close();
                System.out.println("Clock closed");
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Clock clock = new Clock();
        int cycles = 5;

        Thread openThread = new Thread(new OpenThread(clock, cycles));
        Thread closeThread = new Thread(new CloseThread(clock, cycles));

        openThread.start();
        closeThread.start();
    }
}
