import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

public class PluginHelper {
    private List<Object> loadedPlugins;

    public PluginHelper() {
        loadedPlugins = new ArrayList<>();
    }

    public void loadPlugin(String pluginClassName) {
        try {
            Class<?> pluginClass = Class.forName(pluginClassName);
            Object pluginInstance = pluginClass.getDeclaredConstructor().newInstance();
            loadedPlugins.add(pluginInstance);
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
            System.out.println("Error loading plugin: " + e.getMessage());
        }
    }

    public void executePlugins() {
        for (Object plugin : loadedPlugins) {
            try {
                Method runMethod = plugin.getClass().getMethod("run");
                runMethod.invoke(plugin);
            } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
                // Skip plugins without a 'run' method
            }
        }
    }
}
```

