import java.io.*;

public class SerializationUtility {
    // Serialize the object to the specified directory
    public <T> void serialize(T obj, String dir) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(dir))) {
            oos.writeObject(obj);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // Deserialize the object from the specified file
    public <T> T deserialize(File file, Class<T> type) {
        T obj = null;
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
            obj = type.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return obj;
    }
}
```

In the `serialize` method, the object is serialized to the specified directory using `ObjectOutputStream`. In the `deserialize` method, the object is deserialized from the specified file using `ObjectInputStream` and then cast to the specified type.

