```java
import java.util.Date;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class EndOfWeekDateGenerator {

    public List<Date> generateEndOfWeekDates(Date currentWeekendDate) {
        LocalDate lastSunday = currentWeekendDate.toInstant().atZone(ZoneId.systemDefault()).toLocalDate().with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.SUNDAY));
        int weeks = 13 * 4; // 13 weeks per month for the last 3 months

        List<Date> endOfWeekDates = Stream.iterate(lastSunday.minusWeeks(weeks), d -> d.plusWeeks(1L))
                .limit(weeks + 1)
                .map(d -> Date.from(d.atStartOfDay(ZoneId.systemDefault()).toInstant()))
                .collect(Collectors.toList());

        return endOfWeekDates;
    }
}
```

In the solution, we first obtain the last Sunday date from the given `currentWeekendDate` using the `TemporalAdjusters.previousOrSame` method. We then calculate the number of weeks for the last three months (13 weeks per month) and use the Stream API to iterate over the weeks, map the dates to end-of-week dates, and collect them into a list. Finally, the list of end-of-week dates is returned.

