import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.util.ArrayList;

public class Season {
    private int seasonNumber;
    private int episodeCount;
    private double averageRating;

    public Season(int seasonNumber, int episodeCount, double averageRating) {
        this.seasonNumber = seasonNumber;
        this.episodeCount = episodeCount;
        this.averageRating = averageRating;
    }

    public static ArrayList<Season> multiSeasonsParser(String seasonsString, int ID) {
        ArrayList<Season> seasons = new ArrayList<>();

        try {
            JSONArray jsonArray = new JSONArray(seasonsString);
            for (int i = 0; i < jsonArray.length(); i++) {
                JSONObject seasonObject = jsonArray.getJSONObject(i);
                int seasonNumber = seasonObject.getInt("seasonNumber");
                int episodeCount = seasonObject.getInt("episodeCount");
                double averageRating = seasonObject.getDouble("averageRating");
                seasons.add(new Season(seasonNumber, episodeCount, averageRating));
            }
        } catch (JSONException e) {
            // Handle JSON parsing exception
            e.printStackTrace();
        }

        return seasons;
    }
}
```
The `multiSeasonsParser` method takes the input JSON string and an ID as parameters. It uses the `org.json` library to parse the JSON string and extract the season information. For each season object in the JSON array, it creates a new Season object and adds it to the ArrayList. If any JSON parsing exception occurs, it is caught and handled by printing the stack trace. The method returns the ArrayList of Season objects.

