import com.cloudbees.syslog.SyslogMessage;
import com.cloudbees.syslog.sender.UdpSyslogMessageSender;

import java.io.IOException;
import java.util.concurrent.TimeUnit;

public class SyslogMessageSender {
    private final UdpSyslogMessageSender messageSender;

    public SyslogMessageSender(String serverAddress, int port) {
        messageSender = new UdpSyslogMessageSender();
        messageSender.setDefaultMessageHostname("localhost"); // Set default hostname
        messageSender.setDefaultAppName("MyApp"); // Set default app name
        messageSender.setDefaultFacility(UdpSyslogMessageSender.Facility.USER);
        messageSender.setDefaultSeverity(UdpSyslogMessageSender.Severity.INFORMATIONAL);
        messageSender.setSyslogServerHostname(serverAddress);
        messageSender.setSyslogServerPort(port);
    }

    public synchronized void sendMessage(SyslogMessage message) {
        try {
            messageSender.sendMessage(message);
        } catch (IOException e) {
            // Handle the exception, e.g., log it or retry sending the message
            System.err.println("Failed to send syslog message: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        SyslogMessageSender messageSender = new SyslogMessageSender("syslog.example.com", 514);

        // Create and start multiple threads to send messages
        for (int i = 0; i < 5; i++) {
            int finalI = i;
            new Thread(() -> {
                SyslogMessage message = new SyslogMessage();
                message.setMessage("Log message " + finalI);
                messageSender.sendMessage(message);
            }).start();
        }

        // Wait for the threads to finish
        try {
            TimeUnit.SECONDS.sleep(1);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

In the solution, the `SyslogMessageSender` class is implemented with a constructor to set the destination address and port of the Syslog server. The `sendMessage` method is synchronized to ensure thread safety when sending messages. The main method demonstrates the usage of the `SyslogMessageSender` class in a multi-threaded environment by creating and starting multiple threads to send messages to the Syslog server.

