        super(function);
    }

    @Override
    public Stream<BlockPos> getPositions(IWorld world, ChunkGenerator<? extends net.minecraft.world.gen.ChunkGeneratorConfig> generator, Random random, FrequencyConfig config, BlockPos pos) {
        int count = config.count;
        Stream.Builder<BlockPos> positions = Stream.builder();

        for (int i = 0; i < count; i++) {
            int x = pos.getX() + random.nextInt(16);
            int z = pos.getZ() + random.nextInt(16);
            int y = world.getHeight(Heightmap.Type.WORLD_SURFACE, x, z);

            positions.accept(new BlockPos(x, y, z));
        }

        return positions.build();
    }
}
