        private final char emptySymbol = DEFAULT_EMPTY_SYMBOL;

        public String formatGrid(int[][] grid) {
            StringBuilder formattedGrid = new StringBuilder();
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (j > 0) {
                        formattedGrid.append(" ");
                    }
                    if (grid[i][j] == 0) {
                        formattedGrid.append(emptySymbol);
                    } else {
                        formattedGrid.append(grid[i][j]);
                    }
                    if (j < grid[i].length - 1) {
                        formattedGrid.append(" |");
                    }
                }
                formattedGrid.append("\n");
                if (i < grid.length - 1) {
                    formattedGrid.append("-".repeat(21)).append("\n");
                }
            }
            return formattedGrid.toString();
        }
    };
}
