```java
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.ForkJoinWorkerThread;

public class CustomThreadPool {
    private static CustomThreadPool instance;
    private static final Logger logger = LogManager.getLogger(CustomThreadPool.class);
    private final ExecutorService executorService;

    private CustomThreadPool() {
        executorService = new ForkJoinPool();
    }

    public static CustomThreadPool getInstance() {
        if (instance == null) {
            instance = new CustomThreadPool();
        }
        return instance;
    }

    public void submitTask(CompletableFuture<Void> task, String taskName) {
        task.thenAccept(result -> {
            String executionResult = result != null ? "Success" : "Failure";
            String logMessage = "Task '" + taskName + "' execution result: " + executionResult;
            logger.info(logMessage);
            try {
                ObjectMapper objectMapper = new ObjectMapper();
                objectMapper.enable(SerializationFeature.INDENT_OUTPUT);
                String jsonResult = objectMapper.writeValueAsString(new TaskExecutionResult(taskName, executionResult));
                logger.info("Task execution details: " + jsonResult);
            } catch (JsonProcessingException e) {
                logger.error("Error serializing task execution details to JSON: " + e.getMessage());
            }
        });
        executorService.execute(() -> task.join());
    }

    private static class TaskExecutionResult {
        private String taskName;
        private String executionResult;

        public TaskExecutionResult(String taskName, String executionResult) {
            this.taskName = taskName;
            this.executionResult = executionResult;
        }

        public String getTaskName() {
            return taskName;
        }

        public String getExecutionResult() {
            return executionResult;
        }
    }
}
```

This solution provides a custom thread pool class `CustomThreadPool` that meets the specified requirements. The `getInstance()` method ensures a singleton instance, and the `submitTask()` method allows tasks to be submitted for execution. The task execution is logged using Log4j, and the execution results are serialized into JSON using the Jackson library.

