public class BrowserState {
    private enum BrowserStatus {
        INITIALIZING, LOADING, LOADED
    }

    private BrowserStatus browserStatus;

    public void transitionToState(BrowserStatus newStatus) {
        switch (browserStatus) {
            case INITIALIZING:
                if (newStatus != BrowserStatus.LOADING) {
                    throw new UnexpectedBrowserStateException("Cannot switch from "
                            + this.browserStatus + " to " + newStatus);
