import java.util.concurrent.*;

public class ConcurrentTaskExecutor {
    private ExecutorService executorService;

    public ConcurrentTaskExecutor() {
        this.executorService = Executors.newFixedThreadPool(2);
    }

    public long calculateFactorial(int number) {
        long factorial = 1;
        for (int i = 1; i <= number; i++) {
            factorial *= i;
        }
        return factorial;
    }

    public double calculateSquareRoot(int number) {
        return Math.sqrt(number);
    }

    public void executeTasks() {
        Future<Long> factorialFuture = executorService.submit(() -> calculateFactorial(5));
        Future<Double> squareRootFuture = executorService.submit(() -> calculateSquareRoot(25));

        try {
            System.out.println("Factorial of 5: " + factorialFuture.get());
            System.out.println("Square root of 25: " + squareRootFuture.get());
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }

        executorService.shutdown();
    }

    public static void main(String[] args) {
        ConcurrentTaskExecutor taskExecutor = new ConcurrentTaskExecutor();
        taskExecutor.executeTasks();
    }
}
