     * @param inputXML The input XML string to be processed.
     * @return The modified XML string after extracting specific information.
     */
    public String processXML(String inputXML) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(new InputSource(new StringReader(inputXML)));

            NodeList nameNodes = doc.getElementsByTagName("name");
            for (int i = 0; i < nameNodes.getLength(); i++) {
                Element nameElement = (Element) nameNodes.item(i);
                String nameValue = nameElement.getTextContent();

                Element modifiedNameElement = doc.createElement("modifiedName");
                modifiedNameElement.appendChild(doc.createTextNode(nameValue));
                nameElement.getParentNode().appendChild(modifiedNameElement);
            }

            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer();
            StringWriter writer = new StringWriter();
            transformer.transform(new DOMSource(doc), new StreamResult(writer));

            return writer.toString();
        } catch (Exception e) {
            e.printStackTrace();
            return "Error processing XML";
        }
    }
}
