import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class ConnectionPool {
    private final PoolableConnection[] pool;
    private final AtomicLong counter;
    private final long INITIAL_COUNTER_VALUE = 0L;
    private static final long EMPTY_OWNER_VALUE = -1L;
    private final BlockingQueue<PoolableConnection> availableConnections;
    private final ReentrantLock lock;
    private final Condition connectionAvailable;

    public ConnectionPool(int p_capacity) {
        counter = new AtomicLong(INITIAL_COUNTER_VALUE);
        pool = new PoolableConnection[p_capacity];
        availableConnections = new ArrayBlockingQueue<>(p_capacity);
        lock = new ReentrantLock();
        connectionAvailable = lock.newCondition();
        // Initialize the pool with connections
        for (int i = 0; i < p_capacity; i++) {
            PoolableConnection connection = createNewConnection();
            pool[i] = connection;
            availableConnections.add(connection);
        }
    }

    public PoolableConnection acquireConnection() throws InterruptedException {
        lock.lock();
        try {
            while (availableConnections.isEmpty()) {
                connectionAvailable.await();
            }
            PoolableConnection connection = availableConnections.take();
            counter.incrementAndGet();
            return connection;
        } finally {
            lock.unlock();
        }
    }

    public void releaseConnection(PoolableConnection connection) {
        lock.lock();
        try {
            if (counter.get() > 0) {
                counter.decrementAndGet();
                availableConnections.add(connection);
                connectionAvailable.signal();
            }
        } finally {
            lock.unlock();
        }
    }

    private PoolableConnection createNewConnection() {
        // Implement the creation of a new connection
        return new PoolableConnection();
    }
}
```

In the solution, the `ConnectionPool` class is completed with the implementation of the `acquireConnection` and `releaseConnection` methods using a `BlockingQueue` to manage available connections and a `ReentrantLock` with a `Condition` to handle synchronization and signaling between threads. The `acquireConnection` method waits for a connection to become available if all connections are in use, and the `releaseConnection` method correctly releases the connection and notifies waiting threads.

