public class MessageEncoder {
    private static final int OFFSET = 3; // Fixed offset value for encoding and decoding

    public String encodeMessage(String message) {
        byte[] messageBytes = message.getBytes(); // Convert the message to a byte array
        byte[] encodedBytes = new byte[messageBytes.length];

        for (int i = 0; i < messageBytes.length; i++) {
            encodedBytes[i] = (byte) (messageBytes[i] + OFFSET); // Shift each byte by the offset value
        }

        return new String(encodedBytes); // Convert the encoded byte array back to a string
    }

    public String decodeMessage(String encodedMessage) {
        byte[] encodedBytes = encodedMessage.getBytes(); // Convert the encoded message to a byte array
        byte[] decodedBytes = new byte[encodedBytes.length];

        for (int i = 0; i < encodedBytes.length; i++) {
            decodedBytes[i] = (byte) (encodedBytes[i] - OFFSET); // Shift each byte back by the offset value
        }

        return new String(decodedBytes); // Convert the decoded byte array back to the original message string
    }
}
