public class NumberFilter {
    private Integer filterType;

    public NumberFilter(Integer filterType) {
        this.filterType = filterType;
    }

    public List<Integer> filterNumbers(List<Integer> numbers) {
        List<Integer> filteredNumbers = new ArrayList<>();
        for (Integer number : numbers) {
            if (filterType == 1 && number % 2 == 0) { // Even numbers
                filteredNumbers.add(number);
            } else if (filterType == 2 && number % 2 != 0) { // Odd numbers
                filteredNumbers.add(number);
            } else if (filterType == 3 && isPrime(number)) { // Prime numbers
                filteredNumbers.add(number);
            }
        }
        return filteredNumbers;
    }

    private boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }
}
