import org.apache.commons.io.IOUtils;

import java.io.IOException;
import java.io.InputStream;
import java.util.List;
import java.util.stream.Collectors;

public class WordProcessor {
    private List<String> words;

    public WordProcessor() {
        try {
            words = getWords();
        } catch (IOException e) {
            // Handle exception
            e.printStackTrace();
        }
    }

    private List<String> getWords() throws IOException {
        // read file
        InputStream is = WordProcessor.class.getClassLoader().getResourceAsStream("web2.txt");
        List<String> lines = IOUtils.readLines(is, "UTF-8");
        return lines;
    }

    public int countWordsStartingWith(char startChar) {
        return (int) words.stream()
                .filter(word -> word.charAt(0) == startChar)
                .count();
    }

    public String findLongestWord() {
        return words.stream()
                .max((word1, word2) -> Integer.compare(word1.length(), word2.length()))
                .orElse("");
    }

    public static void main(String[] args) {
        WordProcessor wordProcessor = new WordProcessor();
        System.out.println("Count of words starting with 'a': " + wordProcessor.countWordsStartingWith('a'));
        System.out.println("Longest word: " + wordProcessor.findLongestWord());
    }
}
