import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.annotation.processing.SupportedSourceVersion;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.lang.model.element.VariableElement;
import javax.lang.model.type.DeclaredType;
import javax.lang.model.type.TypeMirror;
import javax.lang.model.util.Elements;
import javax.lang.model.util.Types;
import javax.tools.Diagnostic;
import java.io.IOException;
import java.io.Writer;
import java.util.HashSet;
import java.util.Set;

@SupportedAnnotationTypes("com.example.FragmentScope")
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class FragmentScopeProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        Elements elementUtils = processingEnv.getElementUtils();
        Types typeUtils = processingEnv.getTypeUtils();

        for (Element element : roundEnv.getElementsAnnotatedWith(FragmentScope.class)) {
            if (element instanceof TypeElement) {
                TypeElement typeElement = (TypeElement) element;
                String factoryClassName = typeElement.getSimpleName() + "Factory";

                try (Writer writer = processingEnv.getFiler().createSourceFile(factoryClassName).openWriter()) {
                    writer.write(generateFactoryClass(typeElement, elementUtils, typeUtils));
                } catch (IOException e) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error creating " + factoryClassName + ": " + e.getMessage());
                }
            }
        }
        return true;
    }

    private String generateFactoryClass(TypeElement typeElement, Elements elementUtils, Types typeUtils) {
        String packageName = elementUtils.getPackageOf(typeElement).getQualifiedName().toString();
        String className = typeElement.getSimpleName().toString();
        String factoryClassName = className + "Factory";

        StringBuilder factoryClass = new StringBuilder();
        factoryClass.append("package ").append(packageName).append(";\n\n");
        factoryClass.append("public class ").append(factoryClassName).append(" {\n\n");
        factoryClass.append("    public ").append(className).append(" createInstance() {\n");
        factoryClass.append("        // Create instance of ").append(className).append(" within fragment scope\n");
        factoryClass.append("    }\n");
        factoryClass.append("}\n");

        return factoryClass.toString();
    }
}
