```java
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class AdHocThrottleEndpoint {
    private final String _method;
    private final String _path;
    private final Map<String, Map<String, AtomicInteger>> requestCounters = new ConcurrentHashMap<>();

    public AdHocThrottleEndpoint(String method, String path) {
        _method = checkNotNull(method, "method").toUpperCase();
        _path = checkNotNull(path, "path");
    }

    public boolean isRequestAllowed(String method, String path, int maxRequests, int timeFrameSeconds) {
        String methodKey = method.toUpperCase();
        Map<String, AtomicInteger> pathCounters = requestCounters.computeIfAbsent(methodKey, k -> new ConcurrentHashMap<>());
        AtomicInteger counter = pathCounters.computeIfAbsent(path, k -> new AtomicInteger(0));

        synchronized (counter) {
            long currentTime = System.currentTimeMillis() / 1000;
            if (counter.get() == 0 || currentTime - counter.get() > timeFrameSeconds) {
                counter.set(1);
                return true;
            } else if (counter.incrementAndGet() <= maxRequests) {
                return true;
            } else {
                return false;
            }
        }
    }

    private static <T> T checkNotNull(T reference, String message) {
        if (reference == null) {
            throw new NullPointerException(message);
        }
        return reference;
    }
}
```

In the solution, we use a `ConcurrentHashMap` to store request counters for each method-path combination. We use `AtomicInteger` to ensure thread-safe increment operations. The `isRequestAllowed` method checks the request count for the given method and path, and if it exceeds the maximum allowed within the specified time frame, it returns `false`. Otherwise, it updates the counter and returns `true`. The method also handles concurrent requests using synchronized blocks to ensure thread safety.

