import javax.net.ssl.TrustManager;

public final class SslConfigBuilder {
    private TrustManager trustManager;
    private KeyManager keyManager;
    private String[] protocols;
    private String[] cipherSuites;

    public SslConfigBuilder trustManager(TrustManager trustManager) {
        this.trustManager = trustManager;
        return this;
    }

    public SslConfigBuilder keyManager(KeyManager keyManager) {
        this.keyManager = keyManager;
        return this;
    }

    public SslConfigBuilder protocols(String... protocols) {
        this.protocols = protocols;
        return this;
    }

    public SslConfigBuilder cipherSuites(String... cipherSuites) {
        this.cipherSuites = cipherSuites;
        return this;
    }

    public SSLContext build() {
        requireNonNull(trustManager, "TrustManager must be set");
        requireNonNull(keyManager, "KeyManager must be set");
        requireNonNull(protocols, "Protocols must be set");
        requireNonNull(cipherSuites, "CipherSuites must be set");

        SSLContext sslContext;
        try {
            sslContext = SSLContext.getInstance("TLS");
            sslContext.init(new KeyManager[]{keyManager}, new TrustManager[]{trustManager}, null);
            sslContext.getDefaultSSLParameters().setProtocols(protocols);
            sslContext.getDefaultSSLParameters().setCipherSuites(cipherSuites);
        } catch (Exception e) {
            throw new RuntimeException("Error building SSLContext", e);
        }
        return sslContext;
    }
}
