import org.cryptimeleon.math.hash.UniqueByteRepresentable;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class CustomHashFunction implements UniqueByteRepresentable {
    private String input;

    public CustomHashFunction(String input) {
        this.input = input;
    }

    @Override
    public byte[] getUniqueByteRepresentation() {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return digest.digest(input.getBytes());
        } catch (NoSuchAlgorithmException e) {
            // Handle NoSuchAlgorithmException
            e.printStackTrace();
            return new byte[0]; // Return empty byte array in case of exception
        }
    }

    public static void main(String[] args) {
        CustomHashFunction customHash = new CustomHashFunction("Hello, World!");
        byte[] hashValue = customHash.getUniqueByteRepresentation();
        System.out.println("Hash value: " + bytesToHex(hashValue));
    }

    // Helper method to convert byte array to hexadecimal string
    private static String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }
}
