public class Table {
    private Object[][] data;

    public Table() {
        data = new Object[0][0];
    }

    public boolean addRow(Object[] row) {
        if (data.length == 0) {
            data = new Object[1][row.length];
            data[0] = row;
        } else {
            Object[][] newData = new Object[data.length + 1][data[0].length];
            System.arraycopy(data, 0, newData, 0, data.length);
            newData[data.length] = row;
            data = newData;
        }
        return true;
    }

    public boolean add(Object a) {
        if (a instanceof Table) {
            Table table = (Table) a;
            if (data.length == 0) {
                data = new Object[table.data.length][table.data[0].length];
                System.arraycopy(table.data, 0, data, 0, table.data.length);
            } else {
                Object[][] newData = new Object[data.length + table.data.length][data[0].length];
                System.arraycopy(data, 0, newData, 0, data.length);
                System.arraycopy(table.data, 0, newData, data.length, table.data.length);
                data = newData;
            }
            return true;
        }
        return false;
    }
}
