import org.apache.spark.api.java.JavaSparkContext;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class PipelineExecutor {
    private static final Logger LOG = LoggerFactory.getLogger(PipelineExecutor.class);

    public EvaluationContext executePipeline(Pipeline pipeline, JavaSparkContext jssc) {
        try {
            EvaluationContext ctxt;
            if (jssc != null) {
                ctxt = contextFactory.getCtxt(jssc, pipeline);
            } else {
                JavaSparkContext newJsc = SparkContextFactory.getSparkContext(mOptions);
                ctxt = new EvaluationContext(newJsc, pipeline);
            }

            SparkPipelineTranslator translator = new TransformTranslator.Translator();
            pipeline.traverseTopologically(new Evaluator(translator, ctxt));
            ctxt.computeOutputs();

            LOG.info("Pipeline execution complete.");

            return ctxt;
        } catch (Exception e) {
            // Handle exception
            LOG.error("Error executing pipeline: " + e.getMessage());
            return null;
        }
    }
}
