import java.util.Set;
import java.util.regex.Pattern;

public class ResourceHandler {
    public String readFileAsString(String filePath) throws IOException {
        Path path = Paths.get(filePath);
        return new String(Files.readAllBytes(path));
    }

    public Connection establishDatabaseConnection(String url, String username, String password) throws SQLException {
        return DriverManager.getConnection(url, username, password);
    }

    public Set<String> getCachedKeysMatchingPattern(String pattern) {
        Map<String, Object> cache = Util.getCache(); // Assuming Util provides access to the caching system
        Pattern regexPattern = Pattern.compile(pattern);
        Set<String> matchingKeys = cache.keySet().stream()
                .filter(key -> regexPattern.matcher(key).matches())
                .collect(Collectors.toSet());
        return matchingKeys;
    }
}
```

