        try (BufferedReader br = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.startsWith("v ")) {
                    vertices.add(line);
                } else if (line.startsWith("f ")) {
                    faces.add(line);
                }
                linesCount++;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return "File '" + fileName + "' loaded. Lines: " + linesCount + ", vertices: " + vertices.size() + ", faces: " + faces.size();
    }

