        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.print("Enter command: ");
            String[] input = scanner.nextLine().split(" ");

            if (input[0].equals("create")) {
                String name = input[1];
                double initialBalance = Double.parseDouble(input[2]);
                int accountNumber = bankingSystem.createAccount(name, initialBalance);
                System.out.println("Account created successfully. Account number is " + accountNumber);
            } else if (input[0].equals("deposit")) {
                int accountNumber = Integer.parseInt(input[1]);
                double amount = Double.parseDouble(input[2]);
                bankingSystem.deposit(accountNumber, amount);
            } else if (input[0].equals("withdraw")) {
                int accountNumber = Integer.parseInt(input[1]);
                double amount = Double.parseDouble(input[2]);
                bankingSystem.withdraw(accountNumber, amount);
            } else if (input[0].equals("balance")) {
                int accountNumber = Integer.parseInt(input[1]);
                bankingSystem.getBalance(accountNumber);
            } else {
                System.out.println("Invalid command");
            }
        }
    }
}
