@Target({ElementType.FIELD, ElementType.METHOD, ElementType.PARAMETER, ElementType.ANNOTATION_TYPE})
@Retention(RetentionPolicy.RUNTIME)
@Constraint(validatedBy = ValidNomeValidator.class)
@Documented
public @interface ValidNome {
    String message() default "Nome deve ter entre 3 e 50 caracteres";
    Class<?>[] groups() default {};
    Class<? extends Payload>[] payload() default {};
}

import javax.validation.ConstraintValidator;
import javax.validation.ConstraintValidatorContext;

public class ValidNomeValidator implements ConstraintValidator<ValidNome, String> {
    @Override
    public void initialize(ValidNome constraintAnnotation) {
    }

    @Override
    public boolean isValid(String value, ConstraintValidatorContext context) {
        return value != null && value.length() >= 3 && value.length() <= 50;
    }
}

