import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;
import java.text.ParseException;
import java.text.SimpleDateFormat;

public class OAuthResponseParser {
    private String errorCode;

    @JSONField(name = "errmsg")
    private String errorMessage;

    @JSONField(format = "yyyy-MM-dd HH:mm:ss")
    private Date expiryStartTime;

    @JSONField(format = "yyyy-MM-dd HH:mm:ss")
    private Date expiryEndTime;

    public String getOAuthToken() {
        return oAuthToken;
    }

    public String parseErrorCode(String json) {
        JSONObject jsonObject = JSON.parseObject(json);
        return jsonObject.getString("errorCode") != null ? jsonObject.getString("errorCode") : "No error code found";
    }

    public boolean validateExpiryDates(String json) {
        JSONObject jsonObject = JSON.parseObject(json);
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        String expiryStartStr = jsonObject.getString("expiryStartTime");
        String expiryEndStr = jsonObject.getString("expiryEndTime");

        if (expiryStartStr != null && expiryEndStr != null) {
            try {
                Date expiryStart = dateFormat.parse(expiryStartStr);
                Date expiryEnd = dateFormat.parse(expiryEndStr);
                return expiryEnd.after(expiryStart);
            } catch (ParseException e) {
                return false; // Invalid date format
            }
        }
        return false; // Missing fields
    }
}
```

