public Unbatch<T> batch(List<T> data, int batchSize) {
  List<List<T>> batches = new ArrayList<>();
  for (int i = 0; i < data.size(); i += batchSize) {
    int end = Math.min(i + batchSize, data.size());
    batches.add(data.subList(i, end));
