public class MultiClientServer {
    public static void main(String[] args) {
        int portNumber = 12345; // Specify the port number for the server
        try {
            ServerSocket serverSocket = new ServerSocket(portNumber);
            System.out.println("Server is running and listening on port " + portNumber);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("New client connected: " + clientSocket);

                // Create a new thread to handle the client connection
                ClientHandler clientHandler = new ClientHandler(clientSocket);
                clientHandler.start();
            }
        } catch (IOException e) {
            System.err.println("Error occurred while running the server: " + e.getMessage());
        }
    }
}

class ClientHandler extends Thread {
    private Socket clientSocket;
    private PrintWriter out;
    private BufferedReader in;

    public ClientHandler(Socket socket) {
        this.clientSocket = socket;
    }

    public void run() {
        try {
            out = new PrintWriter(clientSocket.getOutputStream(), true);
            in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));

            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                System.out.println("Received from client: " + inputLine);
                // Process the input and send a response back to the client
                String response = processInput(inputLine);
                out.println(response);
            }

            System.out.println("Client disconnected: " + clientSocket);
            clientSocket.close();
        } catch (IOException e) {
            System.err.println("Error occurred while handling client connection: " + e.getMessage());
        }
    }

    private String processInput(String input) {
        // Implement the logic to process the input and generate a response
        // Example: Echo back the received message
        return "Server received: " + input;
    }
}
```

