import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;

public class CustomLogger {
    private LogLevel logLevel;
    private String logFormat;
    private LogDestination logDestination;

    public CustomLogger(String configFilePath) {
        Properties properties = new Properties();
        try (FileInputStream input = new FileInputStream(configFilePath)) {
            properties.load(input);
            configureLogger(properties);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void configureLogger(Properties properties) {
        String level = properties.getProperty("logLevel");
        logLevel = LogLevel.valueOf(level);

        logFormat = properties.getProperty("logFormat");

        String destination = properties.getProperty("logDestination");
        logDestination = LogDestination.valueOf(destination);
    }

    public void log(LogLevel level, String message) {
        if (level.ordinal() >= logLevel.ordinal()) {
            String formattedMessage = formatLogMessage(level, message);
            outputLogMessage(formattedMessage);
        }
    }

    private String formatLogMessage(LogLevel level, String message) {
        return String.format(logFormat, level, message);
    }

    private void outputLogMessage(String formattedMessage) {
        switch (logDestination) {
            case CONSOLE:
                System.out.println(formattedMessage);
                break;
            case FILE:
                // Write to file implementation
                break;
            // Handle other log destinations
        }
    }

    public enum LogLevel {
        INFO, DEBUG, ERROR
    }

    public enum LogDestination {
        CONSOLE, FILE
    }
}
