/**
 * Concrete implementation of the LinkExtractor interface using Jsoup for HTML parsing.
 */
public class JsoupLinkExtractor implements LinkExtractor {

    @Override
    public Set<URL> extractLinks(URL documentURL) throws IOException {
        Set<URL> extractedLinks = new HashSet<>();
        Document document = Jsoup.connect(documentURL.toString()).get();
