```java
import java.util.Arrays;

// Strategy interface
interface SortAlgorithm {
    void sort(int[] array);
}

// Concrete strategy - QuickSort algorithm
class QuickSort implements SortAlgorithm {
    @Override
    public void sort(int[] array) {
        quickSort(array, 0, array.length - 1);
    }

    private void quickSort(int[] array, int low, int high) {
        if (low < high) {
            int pivotIndex = partition(array, low, high);
            quickSort(array, low, pivotIndex - 1);
            quickSort(array, pivotIndex + 1, high);
        }
    }

    private int partition(int[] array, int low, int high) {
        int pivot = array[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (array[j] < pivot) {
                i++;
                int temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
        int temp = array[i + 1];
        array[i + 1] = array[high];
        array[high] = temp;
        return i + 1;
    }
}

// Context class
class Context {
    private SortAlgorithm sortAlgorithm;

    public Context(SortAlgorithm sortAlgorithm) {
        this.sortAlgorithm = sortAlgorithm;
    }

    public void executeSort(int[] array) {
        long startTime = System.nanoTime();
        sortAlgorithm.sort(array);
        long endTime = System.nanoTime();
        long duration = (endTime - startTime) / 1000000; // Convert to milliseconds
        System.out.println("Sorting time: " + duration + " ms");
    }
}

public class TryQuickSort {
    public static void main(String[] args) {
        SortAlgorithm q = new QuickSort();
        Context context = new Context(q);
        int[] array = new int[10000000];
        // Populate the array with random integers
        for (int i = 0; i < array.length; i++) {
            array[i] = (int) (Math.random() * 1000);
        }
        context.executeSort(array);
        // Verify the sorted array
        System.out.println(Arrays.toString(array));
    }
}
```

In this solution, the QuickSort algorithm is completed to sort the input array in ascending order. The Context class is implemented to execute the sorting algorithm and measure the time taken for sorting. The main method initializes the QuickSort algorithm and the Context, populates the array with random integers, executes the sorting, and verifies the sorted array. This solution demonstrates the use of the strategy design pattern for sorting and efficient handling of a large array of integers.

