import java.util.List;

public class NoopSideEffectDetector implements SideEffectDetector {
    @Override
    public boolean detectSideEffect(List<Runnable> runnables) {
        for (Runnable runnable : runnables) {
            SideEffectObserver observer = new SideEffectObserver();
            runnable.run();
            if (observer.hasSideEffect()) {
                return true;
            }
        }
        return false;
    }
}

class SideEffectObserver {
    private boolean sideEffectDetected;

    public void observeSideEffect() {
        sideEffectDetected = true;
    }

    public boolean hasSideEffect() {
        return sideEffectDetected;
    }
}

interface SideEffectDetector {
    boolean detectSideEffect(List<Runnable> runnables);
}
