import java.util.ArrayList;
import java.util.List;

public class LexicographicalStrings {

    public static List<String> generateStrings(String alphabet, int length) {
        List<String> result = new ArrayList<>();
        generateStringsHelper(alphabet, length, "", result);
        return result;
    }

    private static void generateStringsHelper(String alphabet, int length, String current, List<String> result) {
        if (length == 0) {
            result.add(current);
            return;
        }
        for (int i = 0; i < alphabet.length(); i++) {
            generateStringsHelper(alphabet, length - 1, current + alphabet.charAt(i), result);
        }
    }

    public static void main(String[] args) {
        String alphabet = "abc";
        int length = 2;
        List<String> generatedStrings = generateStrings(alphabet, length);
        for (String str : generatedStrings) {
            System.out.println(str);
        }
    }
}
