public class ParallelArray<T> {
    private T[] elements;

    // Constructor and other methods not shown for brevity

    /**
     * Creates a new ParallelArray holding elements of a different type.
     * @param <U> the type of the elements in the new ParallelArray
     * @param elementType the type of the elements
     * @return a new ParallelArray holding elements of the specified type
     */
    public <U> ParallelArray<U> all(Class<? super U> elementType) {
        // Create a new array of the specified type
        U[] newElements = (U[]) Array.newInstance(elementType, elements.length);

        // Copy elements from the original array to the new array
        for (int i = 0; i < elements.length; i++) {
            newElements[i] = (U) elements[i];
        }

        // Create and return a new ParallelArray with the new elements
        return new ParallelArray<>(newElements);
    }
}
