import org.apache.ignite.IgniteException;
import org.apache.ignite.internal.util.typedef.F;
import java.util.Collection;
import java.util.stream.Collectors;

public class IdleVerifyException extends Exception {
    private Collection<IgniteException> exceptions;

    public IdleVerifyException(Collection<IgniteException> exceptions) {
        if (F.isEmpty(exceptions))
            throw new IllegalArgumentException("Exceptions can't be empty!");

        this.exceptions = exceptions;
    }

    @Override
    public String getMessage() {
        return exceptions.stream()
                .map(Throwable::getMessage)
                .collect(Collectors.joining(", "));
    }

    public int getNumberOfExceptions() {
        return exceptions.size();
    }

    public static void main(String[] args) {
        try {
            // Sample usage of IdleVerifyException
            Collection<IgniteException> exceptionCollection = new ArrayList<>();
            exceptionCollection.add(new IgniteException("First exception"));
            exceptionCollection.add(new IgniteException("Second exception"));
            IdleVerifyException idleVerifyException = new IdleVerifyException(exceptionCollection);

            System.out.println("Number of exceptions: " + idleVerifyException.getNumberOfExceptions());
            System.out.println("Exception messages: " + idleVerifyException.getMessage());
        } catch (IdleVerifyException e) {
            e.printStackTrace();
        }
    }
}
