import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class PatternMatcher {
    public static int[] countMatches(String input) {
        Pattern pB = Pattern.compile("b");
        Pattern pEmpty = Pattern.compile("()");

        Matcher mB = pB.matcher(input);
        Matcher mEmpty = pEmpty.matcher(input);

        int countB = 0;
        int countEmpty = 0;

        while (mB.find()) {
            countB++;
        }

        while (mEmpty.find()) {
            countEmpty++;
        }

        return new int[]{countB, countEmpty};
    }
}
```

