import org.assertj.core.api.Assertions;

public class Version {
    private int major;
    private int minor;
    private int patch;

    public Version(int major, int minor, int patch) {
        this.major = major;
        this.minor = minor;
        this.patch = patch;
    }
}

public class VersionRange {
    private char leftIndicator;
    private Version leftVersion;
    private Version rightVersion;
    private char rightIndicator;

    public VersionRange(String range) {
        String[] versions = range.substring(1, range.length() - 1).split(",");
        this.leftIndicator = range.charAt(0);
        this.rightIndicator = range.charAt(range.length() - 1);
        this.leftVersion = parseVersion(versions[0]);
        this.rightVersion = parseVersion(versions[1]);
    }

    private Version parseVersion(String versionStr) {
        String[] parts = versionStr.split("\\.");
        int major = Integer.parseInt(parts[0]);
        int minor = Integer.parseInt(parts[1]);
        int patch = Integer.parseInt(parts[2]);
        return new Version(major, minor, patch);
    }

    public VersionRange hasFieldOrPropertyWithValue(String field, Object value) {
        switch (field) {
            case "leftIndicator":
                Assertions.assertThat(this.leftIndicator).isEqualTo(value);
                break;
            case "leftVersion":
                Assertions.assertThat(this.leftVersion).isEqualTo(value);
                break;
            case "rightVersion":
                Assertions.assertThat(this.rightVersion).isEqualTo(value);
                break;
            case "rightIndicator":
                Assertions.assertThat(this.rightIndicator).isEqualTo(value);
                break;
        }
        return this;
    }
}
```

