import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class RegexLexer {
    public static List<String> tokenizeRegex(String input) {
        List<String> tokens = new ArrayList<>();
        int i = 0;
        while (i < input.length()) {
            char currentChar = input.charAt(i);
            if (currentChar == '*' || currentChar == '+' || currentChar == '?' || currentChar == '^' ||
                    currentChar == '$' || currentChar == '|' || currentChar == '.') {
                tokens.add(String.valueOf(currentChar));
                i++;
            } else if (currentChar == '\\') {
                if (i + 1 < input.length()) {
                    tokens.add(input.substring(i, i + 2));
                    i += 2;
                } else {
                    // Handle invalid escape sequence
                    throw new IllegalArgumentException("Invalid escape sequence at position " + i);
                }
            } else {
                int j = i + 1;
                while (j < input.length() && !isSpecialCharacter(input.charAt(j))) {
                    j++;
                }
                tokens.add(input.substring(i, j));
                i = j;
            }
        }
        return tokens;
    }

    private static boolean isSpecialCharacter(char c) {
        return c == '*' || c == '+' || c == '?' || c == '^' || c == '$' || c == '|' || c == '.';
    }

    public static void main(String[] args) {
        String input = "a*b|c+";
        List<String> tokens = tokenizeRegex(input);
        System.out.println(tokens);  // Output: ["a", "*", "b", "|", "c", "+"]
    }
}
