        return Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
    }

    public int[] closestPoint(int x, int y) {
        int[] closest = points.get(0);
        double minDistance = distance(x, y, closest[0], closest[1]);

        for (int[] point : points) {
            double dist = distance(x, y, point[0], point[1]);
            if (dist < minDistance) {
                minDistance = dist;
                closest = point;
            }
        }

        return closest;
    }
}
