public class I2CController {
    private I2CDevice i2cDevice;

    public void openDevice(int bus, int address) {
        closeDevice(); // Close any existing connection
        try {
            i2cDevice = I2CDevice.builder(bus, address).build();
        } catch (RuntimeIOException e) {
            System.err.println("Error opening I2C device: " + e.getMessage());
        }
    }

    public void writeByte(byte data) {
        try {
            i2cDevice.writeByte(data);
        } catch (RuntimeIOException e) {
            System.err.println("Error writing to I2C device: " + e.getMessage());
        }
    }

    public byte readByte() {
        try {
            return i2cDevice.readByte();
        } catch (RuntimeIOException e) {
            System.err.println("Error reading from I2C device: " + e.getMessage());
            return 0; // Return default value in case of error
        }
    }

    public void closeDevice() {
        if (i2cDevice != null) {
            try {
                i2cDevice.close();
            } catch (RuntimeIOException e) {
                System.err.println("Error closing I2C device: " + e.getMessage());
            } finally {
                i2cDevice = null;
            }
        }
    }
}
