import com.google.gson.Gson;

public class JsonProcessor {
    private Gson gson;

    public JsonProcessor() {
        this.gson = new Gson();
    }

    public <T> T processJsonElement(String jsonElement, Class<T> pojoType) {
        try {
            return gson.fromJson(jsonElement, pojoType);
        } catch (Exception e) {
            // Handle the exception by returning the default value for the POJO type
            try {
                return pojoType.getDeclaredConstructor().newInstance();
            } catch (Exception ex) {
                // If the default value cannot be created, return null
                return null;
            }
        }
    }

