    public Stack() {
        elements = new int[100];
        top = -1;
    }

    public void push(int element) {
        if (top < 99) {
            top++;
            elements[top] = element;
        }
    }

    public int pop() {
        if (top >= 0) {
            int popped = elements[top];
            top--;
            return popped;
        }
        return -1;
    }

    public int top() {
        if (top >= 0) {
            return elements[top];
        }
        return -1;
    }

    public boolean isEmpty() {
        return top == -1;
    }
}
