```java
import com.mongodb.MongoClient;
import com.mongodb.client.MongoCollection;
import com.mongodb.client.MongoDatabase;
import org.bson.Document;

import java.util.ArrayList;
import java.util.List;

public class LibraryManager {
    private MongoClient client;
    private MongoDatabase db;
    private boolean isMongoOnline;

    public LibraryManager() {
        try {
            client = new MongoClient("localhost", 27017);
            db = client.getDatabase("library");
            isMongoOnline = true;
        } catch (Exception e) {
            isMongoOnline = false;
            e.printStackTrace();
        }
    }

    public void insertBook(Book book) {
        if (isMongoOnline) {
            MongoCollection<Document> collection = db.getCollection("books");
            Document doc = new Document("title", book.getTitle())
                    .append("author", book.getAuthor())
                    .append("year", book.getYear());
            collection.insertOne(doc);
        } else {
            System.out.println("MongoDB is not online. Cannot insert book.");
        }
    }

    public void removeBook(String title) {
        if (isMongoOnline) {
            MongoCollection<Document> collection = db.getCollection("books");
            collection.deleteOne(new Document("title", title));
        } else {
            System.out.println("MongoDB is not online. Cannot remove book.");
        }
    }

    public void updateBook(String title, Book updatedBook) {
        if (isMongoOnline) {
            MongoCollection<Document> collection = db.getCollection("books");
            Document filter = new Document("title", title);
            Document update = new Document("$set", new Document("title", updatedBook.getTitle())
                    .append("author", updatedBook.getAuthor())
                    .append("year", updatedBook.getYear()));
            collection.updateOne(filter, update);
        } else {
            System.out.println("MongoDB is not online. Cannot update book.");
        }
    }

    public List<Book> getAllBooks() {
        List<Book> books = new ArrayList<>();
        if (isMongoOnline) {
            MongoCollection<Document> collection = db.getCollection("books");
            for (Document doc : collection.find()) {
                Book book = new Book(doc.getString("title"), doc.getString("author"), doc.getInteger("year"));
                books.add(book);
            }
        } else {
            System.out.println("MongoDB is not online. Cannot retrieve books.");
        }
        return books;
    }
}
