import java.util.Arrays;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class WordCounter {
    public static void main(String[] args) {
        List<String> strings = Arrays.asList("The cat is on the mat.", "Cats are cute!", "category");
        String word = "cat";
        int occurrences = countWordOccurrences(strings, word);
        System.out.println("Total occurrences of the word '" + word + "': " + occurrences);
