import java.util.HashMap;
import java.util.Map;

public class ResourceNamingStrategy {
    private Map<String, String> namingPatterns;

    public ResourceNamingStrategy() {
        this.namingPatterns = new HashMap<>();
    }

    public void setNamingPattern(String resourceType, String namingPattern) {
        namingPatterns.put(resourceType, namingPattern);
    }

    public String generateResourceName(String resourceType, Map<String, String> placeholders) {
        String namingPattern = namingPatterns.get(resourceType);
        if (namingPattern == null) {
            throw new IllegalArgumentException("Naming pattern not set for resource type: " + resourceType);
        }

        for (Map.Entry<String, String> entry : placeholders.entrySet()) {
            namingPattern = namingPattern.replace("{" + entry.getKey() + "}", entry.getValue());
        }

        return namingPattern;
    }

    public static void main(String[] args) {
        ResourceNamingStrategy strategy = new ResourceNamingStrategy();
        strategy.setNamingPattern("file", "file_{date}_{name}");

        Map<String, String> placeholders = new HashMap<>();
        placeholders.put("date", "20220101");
        placeholders.put("name", "document");

        String fileName = strategy.generateResourceName("file", placeholders);
        System.out.println("Generated file name: " + fileName);
    }
}
```

