/**
 * Applies the m-over-n flip unary operator to the given bit string.
 * @param bitString
 *          the input bit string
 * @return the bit string after applying the unary operator
 */
public String apply(final String bitString) {
  int m = mN / 10; // Extract m from mN
  int n = mN % 10; // Extract n from mN
  StringBuilder result = new StringBuilder();
  for (int i = 0; i < bitString.length(); i++) {
    if (i % n < m) {
      result.append(bitString.charAt(i) == '0' ? '1' : '0'); // Flip 0 to 1 and vice versa
    } else {
      result.append(bitString.charAt(i)); // Keep the bit unchanged
    }
  }
  return result.toString();
