import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;

// Interface for backup callback
interface IBackupCallback {
    void operationComplete(long result);
}

// RemoteResult class to encapsulate the transaction result
class RemoteResult {
    private final long result;

    private RemoteResult(long result) {
        this.result = result;
    }

    static RemoteResult of(long result) {
        return new RemoteResult(result);
    }

    long getResult() {
        return result;
    }
}

// Implementation of FutureBackupCallback
class FutureBackupCallback implements IBackupCallback {
    private final CompletableFuture<RemoteResult> mFuture;

    FutureBackupCallback(CompletableFuture<RemoteResult> future) {
        mFuture = future;
    }

    @Override
    public void operationComplete(long result) {
        mFuture.complete(RemoteResult.of(result));
    }
}

// BankAccount class with backup callback support
class BankAccount {
    private long balance;
    private IBackupCallback backupCallback;

    BankAccount() {
        this.balance = 0;
    }

    void setBackupCallback(IBackupCallback backupCallback) {
        this.backupCallback = backupCallback;
    }

    void deposit(long amount) {
        balance += amount;
        if (backupCallback != null) {
            backupCallback.operationComplete(balance);
        }
    }

    void withdraw(long amount) {
        if (balance >= amount) {
            balance -= amount;
            if (backupCallback != null) {
                backupCallback.operationComplete(balance);
            }
        } else {
            System.out.println("Insufficient funds");
        }
    }

    long checkBalance() {
        return balance;
    }
}

// Example usage
public class Main {
    public static void main(String[] args) {
        BankAccount account = new BankAccount();
        CompletableFuture<RemoteResult> future = new CompletableFuture<>();
        FutureBackupCallback backupCallback = new FutureBackupCallback(future);
        account.setBackupCallback(backupCallback);

        account.deposit(100);
        account.withdraw(30);

        try {
            RemoteResult result = future.get();
            System.out.println("Final balance: " + result.getResult());
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }
    }
}
```

