import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.element.Element;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import java.io.IOException;
import java.io.Writer;
import java.util.Set;

@SupportedAnnotationTypes("RestController")
public class RestControllerAnnotationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(RestController.class)) {
            if (element instanceof TypeElement) {
                TypeElement typeElement = (TypeElement) element;
                String className = typeElement.getQualifiedName().toString();
                generateControllerMapping(className);
            }
        }
        return true;
    }

    private void generateControllerMapping(String className) {
        // Generate controller mapping based on the annotated class
        String mapping = "/api/" + className.toLowerCase(); // Example mapping generation
        try (Writer writer = processingEnv.getFiler().createSourceFile(className + "Mapping").openWriter()) {
            writer.write("Controller mapping: " + mapping);
        } catch (IOException e) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Failed to generate mapping for " + className);
        }
    }
}
```

