    public void populateChart(Map<String, List<Double>> dataSeries) {
        for (Map.Entry<String, List<Double>> entry : dataSeries.entrySet()) {
            DataSeries series = new DataSeries();
            series.setName(entry.getKey());
            List<Double> data = entry.getValue();
            for (int i = 0; i < data.size(); i++) {
                double value = data.get(i);
                PlotOptionsLine plotOptions = new PlotOptionsLine();
                if (i < data.size() - 1) {
                    double nextValue = data.get(i + 1);
                    if (nextValue > value) {
                        plotOptions.setColor(Color.GREEN);
                    } else {
                        plotOptions.setColor(Color.RED);
                    }
                }
                DataSeriesItem item = new DataSeriesItem(i, value);
                item.setPlotOptions(plotOptions);
                series.add(item);
            }
            chart.getConfiguration().addSeries(series);
        }
        chart.drawChart();
    }
}
