// Implement the IncrementalSnapshotStrategy class
public class IncrementalSnapshotStrategy<T> implements TakeSnapshotStrategy<T> {
    private Snapshot<T> lastSnapshot;

    public IncrementalSnapshotStrategy(Snapshot<T> lastSnapshot) {
        this.lastSnapshot = lastSnapshot;
    }

    @Override
    public Snapshot<T> takeSnapshot(T document) {
        // Take an incremental snapshot by capturing only the changes since the last snapshot
        // For demonstration purposes, assume the document has a method to calculate changes
        T changes = calculateChanges(document, lastSnapshot.getDocumentState());
        return new Snapshot<>(changes);
    }

    private T calculateChanges(T currentDocument, T lastDocument) {
