import java.io.IOException;
import java.nio.file.*;
import java.util.HashMap;
import java.util.Map;

public class IOUtils {
    public static Map<String, Path> getAllFiles(String directoryPath) {
        Map<String, Path> allFiles = new HashMap<>();
        try {
            Files.walk(Paths.get(directoryPath))
                    .filter(Files::isRegularFile)
                    .forEach(path -> {
                        String relativePath = directoryPath.isEmpty() ? path.toString() : path.toString().replace(directoryPath, "");
                        allFiles.put(relativePath, path);
                    });
        } catch (IOException e) {
            e.printStackTrace();
        }
        return allFiles;
    }
}
