```java
import java.util.Arrays;
import java.util.List;

class Student {
    private String name;
    private List<Integer> grades;

    public Student(String name, List<Integer> grades) {
        this.name = name;
        this.grades = grades;
    }

    public double calculateAverageGrade() {
        int sum = 0;
        for (int grade : grades) {
            sum += grade;
        }
        return (double) sum / grades.size();
    }
}

public class Main {
    public static String findTopStudent(List<Student> students) {
        double maxAverage = Double.MIN_VALUE;
        String topStudent = "";
        for (Student student : students) {
            double average = student.calculateAverageGrade();
            if (average > maxAverage) {
                maxAverage = average;
                topStudent = student.name;
            }
        }
        return topStudent;
    }

    public static void main(String[] args) {
        Student student1 = new Student("Alice", Arrays.asList(85, 90, 92));
        Student student2 = new Student("Bob", Arrays.asList(78, 80, 82));
        Student student3 = new Student("Charlie", Arrays.asList(90, 95, 88));
        List<Student> students = Arrays.asList(student1, student2, student3);
        System.out.println(findTopStudent(students));
    }
}
```

