import java.util.ArrayList;
import java.util.List;

interface Subscriber {
    void onSubscribe(String user);
    void onUnsubscribe(String user);
    void onNotify(String message);
}

class SubscriptionManager {
    private List<Subscriber> subscribers;

    public SubscriptionManager() {
        subscribers = new ArrayList<>();
    }

    public void subscribe(String user) {
        for (Subscriber subscriber : subscribers) {
            subscriber.onSubscribe(user);
        }
    }

    public void unsubscribe(String user) {
        for (Subscriber subscriber : subscribers) {
            subscriber.onUnsubscribe(user);
        }
    }

    public void notifySubscribers(String message) {
        for (Subscriber subscriber : subscribers) {
            subscriber.onNotify(message);
        }
    }

    public void addSubscriber(Subscriber subscriber) {
        subscribers.add(subscriber);
    }

    public void removeSubscriber(Subscriber subscriber) {
        subscribers.remove(subscriber);
    }
}
```

