public String reverseWords(String inputString) {
    String[] words = inputString.split(" "); // Split the input string into individual words
    StringBuilder reversedString = new StringBuilder();

    for (int i = words.length - 1; i >= 0; i--) {
        reversedString.append(words[i]); // Append each word in reverse order
        if (i != 0) {
            reversedString.append(" "); // Add a space between words, except for the last word
        }
    }

    return reversedString.toString();
}
