public class CumulativeProbabilityCalculator {
    public static void main(String[] args) {
        double lowerBound = -1.96;
        double upperBound = 1.96;
        double expectedCumulativeProbability = 0.9500042097035593;

        // Create a normal distribution with mean 0 and standard deviation 1
        NormalDistributionImpl dist = new NormalDistributionImpl(0, 1);

        try {
            // Calculate the cumulative probability for the given bounds
            double calculatedCumulativeProbability = dist.cumulativeProbability(lowerBound, upperBound);

            // Verify if the calculated cumulative probability matches the expected value
            if (Math.abs(calculatedCumulativeProbability - expectedCumulativeProbability) < 1e-10) {
                System.out.println("Cumulative probability calculation is correct.");
            } else {
                System.out.println("Cumulative probability calculation is incorrect.");
            }
        } catch (MathException e) {
            e.printStackTrace();
        }
    }
}
