package com.github.chenjianjx.ssioextsample.spi.clientexternal.base64csv;

import java.io.*;
import java.util.Base64;
import java.util.List;

public class Base64CsvHandler implements Base64SpiConstants {

    @Override
    public String readBase64CsvFile(String filePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            StringBuilder csvData = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                csvData.append(line).append(System.lineSeparator());
            }
            return new String(Base64.getDecoder().decode(csvData.toString()));
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    @Override
    public void writeBase64CsvFile(String filePath, List<String[]> csvData) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filePath))) {
            StringBuilder csvContent = new StringBuilder();
            for (String[] row : csvData) {
                csvContent.append(String.join(String.valueOf(DEFAULT_CSV_CELL_SEPARATOR), row))
                        .append(System.lineSeparator());
            }
            String base64Encoded = Base64.getEncoder().encodeToString(csvContent.toString().getBytes());
            writer.write(base64Encoded);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        Base64CsvHandler handler = new Base64CsvHandler();
        String filePath = "sample.csv";
