public class Geometry {
    public static final double PRECISION = 1e-6;

    // Function to calculate the intersection point between a plane and a line
    public static double planeIntersection(double[] p, double[] s, double[] v, double[] result) {
        double d = -(p[0] * s[0] + p[1] * s[1] + p[2] * s[2] + p[3) / (p[0] * v[0] + p[1] * v[1] + p[2] * v[2]);
        result[0] = s[0] + d * v[0];
        result[1] = s[1] + d * v[1];
        result[2] = s[2] + d * v[2];
        return d;
    }

    // Function to test the intersection calculation
    public static void testIntersection() {
        double[] p = {0, 1, 0, 0}; // Plane parameters
        double[] s = {3, 4, 5}; // Line start point
        double[] v = {1, 2, 3}; // Line direction vector
        double[] exp = {3, 0, 8}; // Expected intersection point

        double[] result = new double[3];
        double t = planeIntersection(p, s, v, result);

        // Assert the intersection point with expected values
        assertEquals(-1, t, PRECISION);
        assertEquals(exp[0], result[0], PRECISION);
        assertEquals(exp[1], result[1], PRECISION);
        assertEquals(exp[2], result[2], PRECISION);
    }

    // Helper function to compare double values with precision
    public static void assertEquals(double expected, double actual, double precision) {
        if (Math.abs(expected - actual) > precision) {
            throw new AssertionError("Expected: " + expected + ", Actual: " + actual);
        }
    }

    public static void main(String[] args) {
        testIntersection();
    }
}
```

