import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import jodd.lagarto.dom.Node;
import jodd.lagarto.dom.Node.NodeType;
import ngoy.core.dom.XDom;

public class ClassNameExtractor {
    public List<String> extractUniqueClassNames(String html) {
        Set<String> classNames = new HashSet<>();
        Node node = XDom.parseHtml(html, 0).children().get(0);
        if (node.getNodeType() == NodeType.ELEMENT) {
            String classAttribute = node.getAttribute("class");
            if (classAttribute != null) {
                String[] individualClasses = classAttribute.split("\\s+");
                for (String className : individualClasses) {
                    if (!className.isEmpty()) {
                        classNames.add(className);
                    }
                }
            }
        }
        return new ArrayList<>(classNames);
    }
}
```

