import io.netty.handler.codec.MessageToByteEncoder;
import io.netty.handler.codec.ByteToMessageDecoder;
import java.util.List;

public final class SpawnXpOrbCodec extends MessageToByteEncoder<SpawnXpOrbMessage> implements ByteToMessageDecoder<SpawnXpOrbMessage> {
    @Override
    protected void encode(ChannelHandlerContext ctx, SpawnXpOrbMessage message, ByteBuf out) throws Exception {
        out.writeInt(message.getEntityId());
        out.writeInt(message.getPosX());
        out.writeInt(message.getPosY());
        out.writeInt(message.getPosZ());
        out.writeInt(message.getXpValue());
