package de.andidog.mobiprint;

import java.util.ArrayList;
import java.util.List;

public class FilteredOrderCollectionAdapter {
    private OrderCollection orderCollection;
    private OrderCollection filteredCollection;

    public FilteredOrderCollectionAdapter(OrderCollection orderCollection) {
        this.orderCollection = orderCollection;
        this.filteredCollection = orderCollection; // Initialize filtered collection with the original collection
    }

    public OrderCollection filterByStatus(String status) {
        List<Order> filteredOrders = new ArrayList<>();
        for (Order order : filteredCollection.getOrders()) {
            if (order.getStatus().equals(status)) {
                filteredOrders.add(order);
            }
        }
        filteredCollection = new OrderCollection(filteredOrders);
        return filteredCollection;
    }

    public OrderCollection filterByCustomer(String customerName) {
        List<Order> filteredOrders = new ArrayList<>();
        for (Order order : filteredCollection.getOrders()) {
            if (order.getCustomerName().equals(customerName)) {
                filteredOrders.add(order);
            }
        }
        filteredCollection = new OrderCollection(filteredOrders);
        return filteredCollection;
    }

    public OrderCollection filterByAmountRange(double minAmount, double maxAmount) {
        List<Order> filteredOrders = new ArrayList<>();
        for (Order order : filteredCollection.getOrders()) {
            if (order.getAmount() >= minAmount && order.getAmount() <= maxAmount) {
                filteredOrders.add(order);
            }
        }
        filteredCollection = new OrderCollection(filteredOrders);
        return filteredCollection;
    }

    public OrderCollection getFilteredOrders() {
        return filteredCollection;
    }
}
```

