import java.util.HashMap;
import java.util.Map;

public class FormProcessor {
    public static String processFormSettings(String... formElementSettings) {
        Map<String, String> formData = new HashMap<>();
        for (String setting : formElementSettings) {
            String[] parts = setting.split("\\(");
            String formElement = parts[1].split(",")[0].trim();
            String data = parts[2].replaceAll("[\"\\)]", "").trim();
            formData.put(formElement, data);
        }

        StringBuilder formattedData = new StringBuilder();
        for (Map.Entry<String, String> entry : formData.entrySet()) {
            formattedData.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        return formattedData.toString();
    }

    public static void main(String[] args) {
        String result = processFormSettings(
                "setFormElement(FORM_USERNAME, \"user123\")",
                "setFormElement(FORM_PASSWORD, \"pass456\")",
                "setFormElement(WebConstants.LOGIN_TOKEN, \"test\")"
        );
        System.out.println(result);
    }
}
