import java.io.PrintStream;

public class PrintVisitor {
    private int indentLevel;
    private char indentChar;
    private PrintStream outputStream;

    public PrintVisitor(int indent, char indentChar, PrintStream out) {
        this.indentLevel = indent;
        this.indentChar = indentChar;
        this.outputStream = out;
    }

    public void visitLeafNode(LeafNode node) {
        printIndentedLine(node.toString());
    }

    public void visitCompositeNode(CompositeNode node) {
        printIndentedLine(node.toString());
        for (Node child : node.getChildren()) {
            if (child instanceof LeafNode) {
                visitLeafNode((LeafNode) child);
            } else if (child instanceof CompositeNode) {
                visitCompositeNode((CompositeNode) child);
            }
        }
    }

    private void printIndentedLine(String line) {
        for (int i = 0; i < indentLevel; i++) {
            outputStream.print(indentChar);
        }
        outputStream.println(line);
    }
}
```

