            System.out.println("Handling ProcessStoppedEvent");
        } else if (event instanceof ProcessUpdatedEvent) {
            System.out.println("Handling ProcessUpdatedEvent");
        }
    }
}

// EventManager class
class EventManager {
    private Map<Class<? extends Event>, List<EventHandler>> eventHandlers = new HashMap<>();

    public void registerHandler(Class<? extends Event> eventClass, EventHandler handler) {
        eventHandlers.computeIfAbsent(eventClass, k -> new ArrayList<>()).add(handler);
    }

    public void unregisterHandler(Class<? extends Event> eventClass, EventHandler handler) {
        eventHandlers.getOrDefault(eventClass, Collections.emptyList()).remove(handler);
    }

    public void dispatch(Event event) {
        List<EventHandler> handlers = eventHandlers.getOrDefault(event.getClass(), Collections.emptyList());
        for (EventHandler handler : handlers) {
            handler.handle(event);
        }
    }
