public void reduce(LongWritable key, Iterable<Segment> values, Context context) throws IOException, InterruptedException {
  // Create a map to store the total revenue for each date
  Map<String, Double> dateRevenueMap = new HashMap<>();

  // Iterate through the segments and calculate the total revenue for each date
  for (Segment trip : values) {
    String date = sdf.format(trip.getDate().getTime());
    double revenue = trip.getRevenue();
    dateRevenueMap.put(date, dateRevenueMap.getOrDefault(date, 0.0) + revenue);
  }

  // Emit key-value pairs where the key is NullWritable.get() and the value is a Text object containing the date and the total revenue generated on that date
  for (Map.Entry<String, Double> entry : dateRevenueMap.entrySet()) {
    String date = entry.getKey();
    double totalRevenue = entry.getValue();
    context.write(NullWritable.get(), new Text(date + " " + totalRevenue));
  }
}
