    public VendingMachine(Map<String, Product> products, Map<String, Double> prices) {
        this.products = products;
        this.prices = prices;
        this.currentBalance = 0.0;
    }

    public void insertCoin(double coin) {
        currentBalance += coin;
    }

    public void selectProduct(String product) {
        if (products.containsKey(product) && products.get(product).getQuantity() > 0 && currentBalance >= prices.get(product)) {
            Product selectedProduct = products.get(product);
            selectedProduct.setQuantity(selectedProduct.getQuantity() - 1);
            currentBalance -= prices.get(product);
            System.out.println("Dispensing " + product);
        } else {
            System.out.println("Insufficient balance or out of stock");
        }
    }

    public double getBalance() {
        return currentBalance;
    }

    public void refund() {
        System.out.println("Refunding: " + currentBalance);
        currentBalance = 0.0;
    }

