public class Library {
    private List<Book> books;

    public Library() {
        this.books = new ArrayList<>();
    }

    public void addBook(Book book) {
        books.add(book);
    }

    public void borrowBook(String title) {
        for (Book book : books) {
            if (book.getTitle().equals(title) && !book.isBorrowed()) {
                book.setBorrowed(true);
                System.out.println("Book '" + title + "' has been borrowed.");
                return;
            }
        }
        System.out.println("Book '" + title + "' is not available for borrowing.");
    }

    public void returnBook(String title) {
        for (Book book : books) {
            if (book.getTitle().equals(title) && book.isBorrowed()) {
                book.setBorrowed(false);
                System.out.println("Book '" + title + "' has been returned.");
                return;
            }
        }
        System.out.println("Book '" + title + "' is not marked as borrowed.");
    }

    public void printAvailableBooks() {
        System.out.println("Available Books:");
        for (Book book : books) {
            if (!book.isBorrowed()) {
                System.out.println(book.getTitle());
            }
        }
    }

    public void printBookDetails(String title) {
        for (Book book : books) {
            if (book.getTitle().equals(title)) {
                System.out.println("Title: " + book.getTitle());
                System.out.println("Author: " + book.getAuthor());
                System.out.println("Borrowed: " + (book.isBorrowed() ? "Yes" : "No"));
                return;
            }
        }
        System.out.println("Book '" + title + "' not found in the library.");
    }
}

