public class MessageProcessor {
    public void listenAppData(String message) {
        if (message.startsWith("MSG:")) {
            String actualMessage = message.substring(4);
            System.out.println("Received message: " + actualMessage);
        } else if (message.startsWith("SYS:")) {
            String systemMessage = message.substring(4);
            // Log the system message to a system log file
            System.out.println("System message logged: " + systemMessage);
        } else if (message.startsWith("ERR:")) {
            String errorMessage = message.substring(4);
            // Raise an exception with the error message
            throw new RuntimeException("Error message received: " + errorMessage);
        } else {
            // Handle unrecognized message types
            System.out.println("Unrecognized message type: " + message);
        }
    }
}
