public void visit(Table table) {
    _sb.append(table.getTableName());
}

@Override
public void visit(Function function) {
    _sb.append(function.getFunctionName()).append("(");
    // Append function arguments
    for (int i = 0; i < function.getParameters().size(); i++) {
        function.getParameters().get(i).accept(this);
        if (i < function.getParameters().size() - 1) {
            _sb.append(", ");
        }
    }
    _sb.append(")");
}

@Override
public void visit(StringValue sv) {
    _sb.append(sv.getValue());
}

@Override
public void visit(SubSelect ss) {
    _sb.append("(");
    // Append subquery
    ss.getSelectBody().accept(this);
    _sb.append(")");
